(326239,36249,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти малюєш зелені ... по стіні вгору і вниз. Респект.'::text,'лінії'::text,'лінію'::text,'лінії'::text,'Ти малюєш зелені лінії по стіні вгору і вниз. Респект.'::text),
(326238,36249,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pintas ... verdes de arriba abajo en la pared. Respeto.'::text,'líneas'::text,'línea'::text,'líneas'::text,'Pintas líneas verdes de arriba abajo en la pared. Respeto.'::text),
(326237,36249,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu peins des ... vertes de haut en bas du mur. Respect.'::text,'lignes'::text,'ligne'::text,'lignes'::text,'Tu peins des lignes vertes de haut en bas du mur. Respect.'::text),
(326240,36249,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duvara aşağı yukarı yeşil ... çiziyorsun. Saygılar.'::text,'çizgiler'::text,'çizgi'::text,'çizgiler'::text,'Duvara aşağı yukarı yeşil çizgiler çiziyorsun. Saygılar.'::text),
(326241,36249,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zöld ... festesz fel-le a falon. Respekt.'::text,'csíkokat'::text,'csíkot'::text,'csíkokat'::text,'Zöld csíkokat festesz fel-le a falon. Respekt.'::text),
(326253,36251,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er streicht grüne Farbe ... die Wand auf dem Dachboden.'::text,'an'::text,'in'::text,'an'::text,'Er streicht grüne Farbe an die Wand auf dem Dachboden.'::text),
(326257,36251,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він наносить зелену фарбу ... стіну на горищі.'::text,'на'::text,'в'::text,'біля'::text,'Він наносить зелену фарбу на стіну на горищі.'::text),
(326256,36251,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Aplica pintura verde ... la pared del desván.'::text,'en'::text,'en'::text,'a'::text,'Aplica pintura verde en la pared del desván.'::text),
(326255,36251,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il met de la peinture verte ... le mur du grenier.'::text,'sur'::text,'dans'::text,'à'::text,'Il met de la peinture verte sur le mur du grenier.'::text),
(326258,36251,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çatı katındaki duvarın ... yeşil boya sürüyor.'::text,'üzerine'::text,'içine'::text,NULL::text,'Çatı katındaki duvarın üzerine yeşil boya sürüyor.'::text),
(326259,36251,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zöld festéket visz fel a padlás ...'::text,'falára'::text,'falában'::text,'falánál'::text,'Zöld festéket visz fel a padlás falára.'::text),
(326262,36252,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Wand hat ... Hälften: grün und grau.'::text,'zwei'::text,'zweite'::text,'Zweien'::text,'Die Wand hat zwei Hälften: grün und grau.'::text),
(326266,36252,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стіна має ... половини: зелену і сіру.'::text,'дві'::text,'другу'::text,'двійки'::text,'Стіна має дві половини: зелену і сіру.'::text),
(326265,36252,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pared tiene ... mitades: verde y gris.'::text,'dos'::text,'segunda'::text,'dos'::text,'La pared tiene dos mitades: verde y gris.'::text),
(326264,36252,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le mur a ... moitiés : verte et grise.'::text,'deux'::text,'deuxième'::text,'deux'::text,'Le mur a deux moitiés : verte et grise.'::text),
(326267,36252,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duvarın ... yarısı var: yeşil ve gri.'::text,'iki'::text,'ikinci'::text,'ikiler'::text,'Duvarın iki yarısı var: yeşil ve gri.'::text),
(326268,36252,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A falnak ... fele van: zöld és szürke.'::text,'két'::text,'második'::text,'kettesek'::text,'A falnak két fele van: zöld és szürke.'::text),
(326280,36254,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wandprojekt: 50 % erledigt, aber es ist nicht mehr ... Farbe übrig.'::text,'viel'::text,'viele'::text,'ein paar'::text,'Wandprojekt: 50 % erledigt, aber es ist nicht mehr viel Farbe übrig.'::text),
(326284,36254,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Проєкт стіни: 50 % готово, але фарби лишилося не ...'::text,'багато'::text,'багато'::text,'кілька'::text,'Проєкт стіни: 50 % готово, але фарби лишилося не багато.'::text),
(326283,36254,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Proyecto pared: 50 % hecho, pero no queda ... pintura.'::text,'mucha'::text,'muchas'::text,'unas pocas'::text,'Proyecto pared: 50 % hecho, pero no queda mucha pintura.'::text),
(326282,36254,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Projet mur : 50 % fait, mais il ne reste pas ... peinture.'::text,'beaucoup de'::text,'beaucoup de'::text,'quelques'::text,'Projet mur : 50 % fait, mais il ne reste pas beaucoup de peinture.'::text),
(326285,36254,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duvar projesi: %50 tamam ama ... boya kalmadı.'::text,'çok'::text,'çok'::text,'birkaç'::text,'Duvar projesi: %50 tamam ama çok boya kalmadı.'::text),
(326286,36254,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Falprojekt: 50% kész, de nem maradt ... festék.'::text,'sok'::text,'sok'::text,'pár'::text,'Falprojekt: 50% kész, de nem maradt sok festék.'::text),
(326289,36255,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... grüne Farbe an der Wand, weil er sie grün streicht.'::text,'ist'::text,'sind'::text,'sein'::text,'Da ist grüne Farbe an der Wand, weil er sie grün streicht.'::text),
(326293,36255,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На стіні ... зелена фарба, бо він фарбує її в зелений.'::text,'є'::text,'є'::text,'бути'::text,'На стіні є зелена фарба, бо він фарбує її в зелений.'::text),
(326292,36255,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pintura verde en la pared porque la pinta de verde.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay pintura verde en la pared porque la pinta de verde.'::text),
(326291,36255,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de la peinture verte sur le mur parce qu''il le peint en vert.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a de la peinture verte sur le mur parce qu''il le peint en vert.'::text),
(326294,36255,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duvarda yeşil boya ... çünkü onu yeşile boyuyor.'::text,'var'::text,'var'::text,'olmak'::text,'Duvarda yeşil boya var çünkü onu yeşile boyuyor.'::text),
(326295,36255,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A falon zöld festék ..., mert zöldre festi.'::text,'van'::text,'vannak'::text,'lenni'::text,'A falon zöld festék van, mert zöldre festi.'::text),
(321546,35728,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei Taucher ... durch das blaue Wasser nach oben.'::text,'schwimmen'::text,'schwimmt'::text,'schwimmend'::text,'Die zwei Taucher schwimmen durch das blaue Wasser nach oben.'::text),
(321550,35728,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Двоє дайверів ... вгору крізь синю воду.'::text,'пливуть'::text,'пливе'::text,'пливучи'::text,'Двоє дайверів пливуть вгору крізь синю воду.'::text),
(321549,35728,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos buceadores ... hacia arriba por el agua azul.'::text,'nadan'::text,'nada'::text,'nadando'::text,'Los dos buceadores nadan hacia arriba por el agua azul.'::text),
(321548,35728,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux plongeurs ... vers le haut dans l''eau bleue.'::text,'nagent'::text,'nage'::text,'nageant'::text,'Les deux plongeurs nagent vers le haut dans l''eau bleue.'::text),
(321551,35728,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki dalgıç mavi suyun içinden yukarı ...'::text,'yüzerler'::text,'yüzer'::text,'yüzerek'::text,'İki dalgıç mavi suyun içinden yukarı yüzerler.'::text),
(321552,35728,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két búvár felfelé ... a kék vízben.'::text,'úszik'::text,'úszik'::text,'úszó'::text,'A két búvár felfelé úszik a kék vízben.'::text),
(321555,35729,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Freitaucher ... ohne Sauerstoffflaschen sehr tief schwimmen.'::text,'können'::text,'können'::text,'sind'::text,'Freitaucher können ohne Sauerstoffflaschen sehr tief schwimmen.'::text),
(321559,35729,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Фридайвери ... плавати дуже глибоко без балонів.'::text,'можуть'::text,'можуть'::text,'є'::text,'Фридайвери можуть плавати дуже глибоко без балонів.'::text),
(321558,35729,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los apneístas ... nadar muy hondo sin botellas de aire.'::text,'pueden'::text,'pueden'::text,'están'::text,'Los apneístas pueden nadar muy hondo sin botellas de aire.'::text),
(321557,35729,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les apnéistes ... nager très profond sans bouteilles d''air.'::text,'peuvent'::text,'peuvent'::text,'sont'::text,'Les apnéistes peuvent nager très profond sans bouteilles d''air.'::text),
(321560,35729,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Serbest dalgıçlar hava tüpü olmadan çok derine ...'::text,'yüzebilir'::text,'yüzebilir'::text,NULL::text,'Serbest dalgıçlar hava tüpü olmadan çok derine yüzebilir.'::text),
(321561,35729,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szabadtüdős búvárok palack nélkül is nagyon mélyre ... úszni.'::text,'tudnak'::text,'tudnak'::text,'vannak'::text,'A szabadtüdős búvárok palack nélkül is nagyon mélyre tudnak úszni.'::text),
(321573,35731,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... die Taucher am Seil entlang auf fünfzig Meter hinunter.'::text,'schwammen'::text,'schwammen'::text,'schwimmen'::text,'Gestern schwammen die Taucher am Seil entlang auf fünfzig Meter hinunter.'::text),
(321577,35731,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора дайвери ... вздовж троса на п''ятдесят метрів униз.'::text,'пливли'::text,'пливли'::text,'пливуть'::text,'Учора дайвери пливли вздовж троса на п''ятдесят метрів униз.'::text),
(321576,35731,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer los buceadores ... por el cabo hasta los cincuenta metros.'::text,'nadaron'::text,'nadaron'::text,'nadan'::text,'Ayer los buceadores nadaron por el cabo hasta los cincuenta metros.'::text),
(321575,35731,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, les plongeurs ... le long du câble jusqu''à cinquante mètres.'::text,'ont nagé'::text,'ont nagé'::text,'nagent'::text,'Hier, les plongeurs ont nagé le long du câble jusqu''à cinquante mètres.'::text),
(321578,35731,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün dalgıçlar ip boyunca elli metreye kadar ...'::text,'yüzdüler'::text,'yüzdüler'::text,'yüzerler'::text,'Dün dalgıçlar ip boyunca elli metreye kadar yüzdüler.'::text),
(321579,35731,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a búvárok a kötél mentén ötven méterig ...'::text,'úsztak'::text,'úsztak'::text,'úsznak'::text,'Tegnap a búvárok a kötél mentén ötven méterig úsztak.'::text),
(321591,35733,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Er ... so schnell nach oben! Das ist total verrückt!'::text,'schwimmt'::text,'schwimmt'::text,'schwimmt'::text,'Nein! Er schwimmt so schnell nach oben! Das ist total verrückt!'::text),
(321595,35733,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Він ... вгору так швидко! Це просто божевілля!'::text,'пливе'::text,'пливе'::text,'пливе'::text,'Ні! Він пливе вгору так швидко! Це просто божевілля!'::text),
(321594,35733,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡... hacia arriba tan rápido! ¡Es una locura total!'::text,'Está nadando'::text,'Nada'::text,'Está nadando'::text,'¡No! ¡Está nadando hacia arriba tan rápido! ¡Es una locura total!'::text),
(321593,35733,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! Il ... vers le haut si vite ! C''est complètement fou !'::text,'est en train de nager'::text,'nage'::text,'est en train de nager'::text,'Non ! Il est en train de nager vers le haut si vite ! C''est complètement fou !'::text),
(321596,35733,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Yukarı çok hızlı ...! Bu tamamen çılgınlık!'::text,'yüzüyor'::text,'yüzer'::text,'yüzüyor'::text,'Hayır! Yukarı çok hızlı yüzüyor! Bu tamamen çılgınlık!'::text),
(321597,35733,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! Olyan gyorsan ... felfelé! Ez teljesen őrület!'::text,'úszik'::text,'úszik'::text,'úszik'::text,'Ne! Olyan gyorsan úszik felfelé! Ez teljesen őrület!'::text),
(321600,35734,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schwimmen nie in Pools, aber jetzt ... sie im tiefen Meer!'::text,'schwimmen'::text,'schwimmen'::text,NULL::text,'Sie schwimmen nie in Pools, aber jetzt schwimmen sie im tiefen Meer!'::text),
(321604,35734,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони ніколи не плавають у басейнах, але зараз ... в глибокому морі!'::text,'плавають'::text,'плавають'::text,NULL::text,'Вони ніколи не плавають у басейнах, але зараз плавають в глибокому морі!'::text),
(321603,35734,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca nadan en piscinas, ¡pero ahora ... en el mar profundo!'::text,'están nadando'::text,'nadan'::text,NULL::text,'Nunca nadan en piscinas, ¡pero ahora están nadando en el mar profundo!'::text),
(321602,35734,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils ne nagent jamais en piscine, mais là ils ... en pleine mer !'::text,'sont en train de nager'::text,'nagent'::text,NULL::text,'Ils ne nagent jamais en piscine, mais là ils sont en train de nager en pleine mer !'::text),
(321605,35734,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havuzda asla yüzmezler ama şimdi derin denizde ...!'::text,'yüzüyorlar'::text,'yüzerler'::text,NULL::text,'Havuzda asla yüzmezler ama şimdi derin denizde yüzüyorlar!'::text),
(321606,35734,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Medencében soha nem úsznak, de most a mély tengerben ...!'::text,'úsznak'::text,'úsznak'::text,NULL::text,'Medencében soha nem úsznak, de most a mély tengerben úsznak!'::text),
(321609,35735,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, er hat mir gesagt, dass er nächstes Mal bis zum Grund schwimmen ...'::text,'wird'::text,'ist'::text,'wird'::text,'Bestie, er hat mir gesagt, dass er nächstes Mal bis zum Grund schwimmen wird.'::text),
(321613,35735,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що наступного разу ... плисти до самого дна.'::text,'буде'::text,'є'::text,'збирається'::text,'Подруго, він сказав мені, що наступного разу буде плисти до самого дна.'::text),
(321612,35735,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me dijo que la próxima vez ... nadar hasta el fondo.'::text,''::text,'está'::text,'va a'::text,'Amiga, me dijo que la próxima vez nadar hasta el fondo.'::text),
(321611,35735,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, il m''a dit que la prochaine fois il ... nager jusqu''au fond.'::text,''::text,'est'::text,'va'::text,'Bestie, il m''a dit que la prochaine fois il nager jusqu''au fond.'::text),
(321614,35735,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kankam, bir dahaki sefere dibe kadar ... söyledi.'::text,'yüzeceğini'::text,NULL::text,'yüzeceğini'::text,'Kankam, bir dahaki sefere dibe kadar yüzeceğini söyledi.'::text),
(321615,35735,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy legközelebb ... leúszni egészen az aljáig.'::text,'fog'::text,'van'::text,'fog'::text,'Csajszi, azt mondta, hogy legközelebb fog leúszni egészen az aljáig.'::text),
(324048,36006,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestandsbericht: Die Jungs ... 2 Kreisel auf dem Tisch.'::text,'haben'::text,'hat'::text,'haben'::text,'Bestandsbericht: Die Jungs haben 2 Kreisel auf dem Tisch.'::text),
(324052,36006,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт про запаси: хлопці ... 2 дзиґи на столі.'::text,'мають'::text,'має'::text,'мають'::text,'Звіт про запаси: хлопці мають 2 дзиґи на столі.'::text),
(324051,36006,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe de stock: los chicos ... 2 peonzas en la mesa.'::text,'tienen'::text,'tiene'::text,'tienen'::text,'Informe de stock: los chicos tienen 2 peonzas en la mesa.'::text),
(324050,36006,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport de stock : les garçons ... 2 toupies sur la table.'::text,'ont'::text,'a'::text,'ont'::text,'Rapport de stock : les garçons ont 2 toupies sur la table.'::text),
(324053,36006,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stok raporu: çocukların masada 2 topacı ...'::text,'var'::text,'var'::text,'var'::text,'Stok raporu: çocukların masada 2 topacı var.'::text),
(324054,36006,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Készletjelentés: a fiúknak ... 2 pörgettyűjük az asztalon.'::text,'van'::text,'van'::text,'van'::text,'Készletjelentés: a fiúknak van 2 pörgettyűjük az asztalon.'::text),
(324057,36007,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Spielzeug ist gelb, weil es gelb ist.'::text,'Dieses'::text,'Diese'::text,'Jene'::text,'Dieses Spielzeug ist gelb, weil es gelb ist.'::text),
(324061,36007,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... іграшка жовта, бо вона жовта.'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Ця іграшка жовта, бо вона жовта.'::text),
(324060,36007,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... juguete es amarillo porque es amarillo.'::text,'Este'::text,'Estos'::text,'Esos'::text,'Este juguete es amarillo porque es amarillo.'::text),
(324059,36007,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... jouet est jaune parce qu''il est jaune.'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Ce jouet est jaune parce qu''il est jaune.'::text),
(324062,36007,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... oyuncak sarı çünkü sarı.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu oyuncak sarı çünkü sarı.'::text),
(324063,36007,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a játék sárga, mert sárga.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a játék sárga, mert sárga.'::text),
(324066,36008,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Dieser lila Kreisel zerstört ... gelbes Spielzeug! Rache!'::text,'mein'::text,'mich'::text,'meins'::text,'Nein! Dieser lila Kreisel zerstört mein gelbes Spielzeug! Rache!'::text),
