(324069,36008,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡Esa peonza morada destroza ... juguete amarillo! ¡Venganza!'::text,'mi'::text,'me'::text,'el mío'::text,'¡No! ¡Esa peonza morada destroza mi juguete amarillo! ¡Venganza!'::text),
