(322882,35876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудові пляжні правила, звісно. Усі гравці ... кидати м''які м''ячі.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Чудові пляжні правила, звісно. Усі гравці мають кидати м''які м''ячі.'::text),
(322881,35876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué normas de playa tan geniales, claro. Todos los jugadores ... lanzar pelotas blandas.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Qué normas de playa tan geniales, claro. Todos los jugadores tienen que lanzar pelotas blandas.'::text),
(322880,35876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super règles de plage, évidemment. Tous les joueurs ... lancer des balles molles.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Super règles de plage, évidemment. Tous les joueurs doivent lancer des balles molles.'::text),
(322883,35876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika plaj kuralları, belli. Bütün oyuncular yumuşak top ...'::text,'atmak zorunda'::text,'atmalı'::text,'atmalı'::text,'Harika plaj kuralları, belli. Bütün oyuncular yumuşak top atmak zorunda.'::text),
(322884,35876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szuper strandszabályok, persze. Minden játékosnak puha labdákat ... dobnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'Szuper strandszabályok, persze. Minden játékosnak puha labdákat kell dobnia.'::text),
(322887,35877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, du ... ihn tiefer werfen, der Ball ist echt hinüber.'::text,'solltest'::text,'sollst'::text,'solltest'::text,'Alter, du solltest ihn tiefer werfen, der Ball ist echt hinüber.'::text),
(322891,35877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ти ... кидати нижче, цей м''яч уже якийсь убитий.'::text,'мав би'::text,'будеш'::text,'мав би'::text,'Бро, ти мав би кидати нижче, цей м''яч уже якийсь убитий.'::text),
(322890,35877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... lanzarla más baja, esa pelota está un poco hecha polvo.'::text,'deberías'::text,'deberás'::text,'deberías'::text,'Tío, deberías lanzarla más baja, esa pelota está un poco hecha polvo.'::text),
(322889,35877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, tu ... la lancer plus bas, cette balle est un peu morte.'::text,'devrais'::text,'devras'::text,'devrais'::text,'Frérot, tu devrais la lancer plus bas, cette balle est un peu morte.'::text),
(322892,35877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onu daha alçaktan ..., o top bayağı bitmiş.'::text,'atmalısın'::text,'atacaksın'::text,'atmalısın'::text,'Kanka, onu daha alçaktan atmalısın, o top bayağı bitmiş.'::text),
(322893,35877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, alacsonyabbra ... dobnod, az a labda eléggé kész van.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Tesó, alacsonyabbra kellene dobnod, az a labda eléggé kész van.'::text),
(322896,35878,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, sie wirft viel zu hoch, ... frisst er Sand.'::text,'also'::text,'weil'::text,'aber'::text,'Nee Alter, sie wirft viel zu hoch, also frisst er Sand.'::text),
(322900,35878,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні, бро, вона кидає занадто високо, ... він їсть пісок.'::text,'тому'::text,'бо'::text,'але'::text,'Ні, бро, вона кидає занадто високо, тому він їсть пісок.'::text),
(322899,35878,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, la lanza demasiado alto, ... él acaba comiendo arena.'::text,'así que'::text,'porque'::text,'pero'::text,'Qué va, tío, la lanza demasiado alto, así que él acaba comiendo arena.'::text),
(322898,35878,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frérot, elle la lance beaucoup trop haut, ... il mange du sable.'::text,'donc'::text,'parce que'::text,'mais'::text,'Non frérot, elle la lance beaucoup trop haut, donc il mange du sable.'::text),
(322901,35878,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, çok yükseğe atıyor, ... o kum yiyor.'::text,'bu yüzden'::text,'çünkü'::text,'ama'::text,'Yok kanka, çok yükseğe atıyor, bu yüzden o kum yiyor.'::text),
(322902,35878,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, túl magasra dobja, ... ő homokot eszik.'::text,'ezért'::text,'mert'::text,'de'::text,'Nem, tesó, túl magasra dobja, ezért ő homokot eszik.'::text),
(305958,33996,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Freunde ... gemeinsam eine riesige Steinkugel bewegen.'::text,'können'::text,'können'::text,'können'::text,'Die Freunde können gemeinsam eine riesige Steinkugel bewegen.'::text),
(305962,33996,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друзі ... разом зрушити величезну кам''яну кулю.'::text,'можуть'::text,'можуть'::text,'можуть'::text,'Друзі можуть разом зрушити величезну кам''яну кулю.'::text),
(305961,33996,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los amigos ... mover juntos una bola de piedra gigante.'::text,'pueden'::text,'pueden'::text,'pueden'::text,'Los amigos pueden mover juntos una bola de piedra gigante.'::text),
(305960,33996,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les amis ... déplacer ensemble une boule de pierre géante.'::text,'peuvent'::text,'peuvent'::text,'peuvent'::text,'Les amis peuvent déplacer ensemble une boule de pierre géante.'::text),
(305963,33996,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar dev bir taş topu birlikte ...'::text,'hareket ettirebilir'::text,'hareket ettirebilir'::text,'hareket ettirebilir'::text,'Arkadaşlar dev bir taş topu birlikte hareket ettirebilir.'::text),
(305964,33996,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátok együtt meg ... mozdítani egy óriási kőgolyót.'::text,'tudnak'::text,'tudnak'::text,'tudnak'::text,'A barátok együtt meg tudnak mozdítani egy óriási kőgolyót.'::text),
(305967,33997,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... bewegt er die große Kiste? Mit der Schulter.'::text,'Wie'::text,'Wer'::text,'Wo'::text,'Wie bewegt er die große Kiste? Mit der Schulter.'::text),
(305971,33997,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він рухає великий ящик? Плечем.'::text,'Як'::text,'Хто'::text,'Де'::text,'Як він рухає великий ящик? Плечем.'::text),
(305970,33997,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... mueve la caja grande? Con el hombro.'::text,'Cómo'::text,'Quién'::text,'Dónde'::text,'¿Cómo mueve la caja grande? Con el hombro.'::text),
(305969,33997,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... déplace-t-il la grande caisse ? Avec l''épaule.'::text,'Comment'::text,'Qui'::text,'Où'::text,'Comment déplace-t-il la grande caisse ? Avec l''épaule.'::text),
(305972,33997,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük sandığı ... hareket ettiriyor? Omzuyla.'::text,'nasıl'::text,'kim'::text,'nerede'::text,'Büyük sandığı nasıl hareket ettiriyor? Omzuyla.'::text),
(305973,33997,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mozgatja a nagy ládát? A vállával.'::text,'Hogyan'::text,'Ki'::text,'Hol'::text,'Hogyan mozgatja a nagy ládát? A vállával.'::text),
(305976,33998,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, er hat mir erzählt, dass er ganz allein ein Auto ...'::text,'bewegte'::text,'bewegte'::text,'bewegen'::text,'Mädel, er hat mir erzählt, dass er ganz allein ein Auto bewegte.'::text),
(305980,33998,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, він сказав мені, що ... машину зовсім сам.'::text,'зрушив'::text,'зрушив'::text,'зрушити'::text,'Подруго, він сказав мені, що зрушив машину зовсім сам.'::text),
(305979,33998,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que ... un coche él solito.'::text,'movió'::text,'movió'::text,'mover'::text,'Tía, me dijo que movió un coche él solito.'::text),
(305978,33998,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, il m''a dit qu''il ... une voiture tout seul.'::text,'a déplacé'::text,'a déplacé'::text,'déplacer'::text,'Ma belle, il m''a dit qu''il a déplacé une voiture tout seul.'::text),
(305981,33998,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana bir arabayı tek başına ... söyledi.'::text,'hareket ettirdiğini'::text,'hareket ettirdiğini'::text,'hareket ettirmek'::text,'Kızım, bana bir arabayı tek başına hareket ettirdiğini söyledi.'::text),
(305982,33998,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy teljesen egyedül ... egy autót.'::text,'elmozdított'::text,'elmozdított'::text,'elmozdítani'::text,'Csajszi, azt mondta, hogy teljesen egyedül elmozdított egy autót.'::text),
(305985,33999,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also anscheinend bewegt er sonst Kisten, aber gestern ... er ein Auto.'::text,'bewegte'::text,'bewegt'::text,NULL::text,'Okay, also anscheinend bewegt er sonst Kisten, aber gestern bewegte er ein Auto.'::text),
(305989,33999,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, він нібито зазвичай пересуває коробки, але вчора ... машину.'::text,'пересунув'::text,'пересуває'::text,NULL::text,'Коротше, він нібито зазвичай пересуває коробки, але вчора пересунув машину.'::text),
(305988,33999,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer normalmente mueve cajas, pero ayer ... un coche.'::text,'movió'::text,'mueve'::text,NULL::text,'Vale, pues al parecer normalmente mueve cajas, pero ayer movió un coche.'::text),
(305987,33999,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment il déplace d''habitude des cartons, mais hier il ... une voiture.'::text,'a déplacé'::text,'déplace'::text,NULL::text,'Bon alors, apparemment il déplace d''habitude des cartons, mais hier il a déplacé une voiture.'::text),
(305990,33999,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, meğer genelde kutuları hareket ettirirmiş ama dün bir araba ...'::text,'hareket ettirdi'::text,'hareket ettirir'::text,NULL::text,'Tamam, meğer genelde kutuları hareket ettirirmiş ama dün bir araba hareket ettirdi.'::text),
(305991,33999,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag általában dobozokat mozgat, de tegnap egy autót ...'::text,'mozgatott'::text,'mozgat'::text,NULL::text,'Oké, szóval állítólag általában dobozokat mozgat, de tegnap egy autót mozgatott.'::text),
(305994,34000,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ich habe gehört, dass er gerade eine riesige Kiste durch ein Lager ...'::text,'bewegt'::text,'bewegt'::text,'bewegt'::text,'Hör zu, ich habe gehört, dass er gerade eine riesige Kiste durch ein Lager bewegt.'::text),
(305998,34000,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, що він саме зараз ... величезний ящик через склад.'::text,'пересуває'::text,'пересуває'::text,'пересуває'::text,'Слухай, я чула, що він саме зараз пересуває величезний ящик через склад.'::text),
(305997,34000,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que ahora mismo ... una caja gigante por un almacén.'::text,'está moviendo'::text,'mueve'::text,'está moviendo'::text,'Oye, me han dicho que ahora mismo está moviendo una caja gigante por un almacén.'::text),
(305996,34000,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, on m''a dit qu''en ce moment il ... une caisse géante à travers un entrepôt.'::text,'est en train de déplacer'::text,'déplace'::text,'est en train de déplacer'::text,'Écoute, on m''a dit qu''en ce moment il est en train de déplacer une caisse géante à travers un entrepôt.'::text),
(305999,34000,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, şu an bir depoda dev bir sandığı ...'::text,'taşıyormuş'::text,'taşırmış'::text,'taşıyormuş'::text,'Dinle, şu an bir depoda dev bir sandığı taşıyormuş.'::text),
(306000,34000,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt hallottam, hogy most épp egy óriási ládát ... át egy raktáron.'::text,'mozgat'::text,'mozgat'::text,'mozgat'::text,'Figyelj, azt hallottam, hogy most épp egy óriási ládát mozgat át egy raktáron.'::text),
(306003,34001,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, die beste Methode: Du ... ein Auto bewegen, indem du es schiebst.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Klar, die beste Methode: Du solltest ein Auto bewegen, indem du es schiebst.'::text),
(306007,34001,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, найкращий спосіб: ти ... рухати машину, штовхаючи її.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Звісно, найкращий спосіб: ти мав би рухати машину, штовхаючи її.'::text),
(306006,34001,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, la mejor forma: ... mover un coche empujándolo.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Obviamente, la mejor forma: deberías mover un coche empujándolo.'::text),
(306005,34001,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, la meilleure méthode : tu ... déplacer une voiture en la poussant.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Évidemment, la meilleure méthode : tu devrais déplacer une voiture en la poussant.'::text),
(306008,34001,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki en iyi yol: bir arabayı iterek ...'::text,'hareket ettirmelisin'::text,'hareket ettirmelisin'::text,'hareket ettirmelisin'::text,'Tabii ki en iyi yol: bir arabayı iterek hareket ettirmelisin.'::text),
(306009,34001,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván a legjobb módszer: egy autót tolással ... mozgatnod.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Nyilván a legjobb módszer: egy autót tolással kellene mozgatnod.'::text),
(299721,33303,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein kleiner Junge ... sich hinter einem Baum im Park.'::text,'versteckt'::text,'verstecken'::text,'versteckend'::text,'Ein kleiner Junge versteckt sich hinter einem Baum im Park.'::text),
(299725,33303,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Маленький хлопчик ... за деревом у парку.'::text,'ховається'::text,'ховатися'::text,'ховаючись'::text,'Маленький хлопчик ховається за деревом у парку.'::text),
(299724,33303,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un niño pequeño se ... detrás de un árbol en el parque.'::text,'esconde'::text,'esconder'::text,'escondiendo'::text,'Un niño pequeño se esconde detrás de un árbol en el parque.'::text),
(299723,33303,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un petit garçon se ... derrière un arbre dans le parc.'::text,'cache'::text,'cacher'::text,'cachant'::text,'Un petit garçon se cache derrière un arbre dans le parc.'::text),
(299726,33303,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küçük bir çocuk parkta bir ağacın arkasına ...'::text,'saklanır'::text,'saklanmak'::text,'saklanarak'::text,'Küçük bir çocuk parkta bir ağacın arkasına saklanır.'::text),
(299727,33303,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy kisfiú egy fa mögé ... a parkban.'::text,'bújik'::text,'bújni'::text,'bújó'::text,'Egy kisfiú egy fa mögé bújik a parkban.'::text),
(299739,33305,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Krass, anscheinend ... sie sich nächstes Jahr wieder hinter dem Sofa verstecken.'::text,'werden'::text,'sind'::text,NULL::text,'Krass, anscheinend werden sie sich nächstes Jahr wieder hinter dem Sofa verstecken.'::text),
(299743,33305,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Та ну, кажуть, наступного року вони знову ... ховатися за диваном.'::text,'будуть'::text,'є'::text,NULL::text,'Та ну, кажуть, наступного року вони знову будуть ховатися за диваном.'::text),
(299742,33305,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No me digas, al parecer el año que viene ... esconderse otra vez detrás del sofá.'::text,''::text,'están'::text,NULL::text,'No me digas, al parecer el año que viene esconderse otra vez detrás del sofá.'::text),
(299741,33305,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sérieux, apparemment l''année prochaine ils ... se cacher encore derrière le canapé.'::text,''::text,'sont'::text,NULL::text,'Sérieux, apparemment l''année prochaine ils se cacher encore derrière le canapé.'::text),
(299744,33305,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Olamaz, galiba seneye yine kanepenin arkasına ...'::text,'saklanacaklar'::text,NULL::text,NULL::text,'Olamaz, galiba seneye yine kanepenin arkasına saklanacaklar.'::text),
(299745,33305,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne már, állítólag jövőre megint a kanapé mögé ... bújni.'::text,'fognak'::text,'vannak'::text,NULL::text,'Ne már, állítólag jövőre megint a kanapé mögé fognak bújni.'::text),
(299748,33306,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, ich habe gehört, dass sie sich zu ihrem Geburtstag hinter dem Sofa verstecken ...'::text,'werden'::text,'wird'::text,'werden'::text,'Rate mal, ich habe gehört, dass sie sich zu ihrem Geburtstag hinter dem Sofa verstecken werden.'::text),
(299752,33306,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вгадай що, я чула, що вони ... сховатися за диваном на її день народження.'::text,'збираються'::text,'збирається'::text,'збираються'::text,'Вгадай що, я чула, що вони збираються сховатися за диваном на її день народження.'::text),
(299751,33306,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, me han dicho que ... esconderse detrás del sofá por su cumpleaños.'::text,'van a'::text,'va a'::text,'van a'::text,'Adivina, me han dicho que van a esconderse detrás del sofá por su cumpleaños.'::text),
(299750,33306,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, on m''a dit qu''ils ... se cacher derrière le canapé pour son anniversaire.'::text,'vont'::text,'va'::text,'vont'::text,'Devine quoi, on m''a dit qu''ils vont se cacher derrière le canapé pour son anniversaire.'::text),
(299753,33306,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, duydum ki onun doğum günü için kanepenin arkasına ...'::text,'saklanacaklarmış'::text,'saklanacakmış'::text,'saklanacaklarmış'::text,'Bil bakalım, duydum ki onun doğum günü için kanepenin arkasına saklanacaklarmış.'::text),
(299754,33306,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy a szülinapjára el ... bújni a kanapé mögé.'::text,'fognak'::text,'fog'::text,'fognak'::text,'Képzeld, azt hallottam, hogy a szülinapjára el fognak bújni a kanapé mögé.'::text),
(299757,33307,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Perfektes Versteck: Eine Hand guckt raus. Sie ... ihn in Sekunden finden.'::text,'werden'::text,'werden'::text,NULL::text,'Perfektes Versteck: Eine Hand guckt raus. Sie werden ihn in Sekunden finden.'::text),
(299761,33307,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бездоганна схованка: стирчить рука. Вони ... знайти його за лічені секунди.'::text,'збираються'::text,'будуть'::text,NULL::text,'Бездоганна схованка: стирчить рука. Вони збираються знайти його за лічені секунди.'::text),
(299760,33307,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escondite perfecto: asoma una mano. ... encontrarlo en segundos.'::text,'Van a'::text,NULL::text,NULL::text,'Escondite perfecto: asoma una mano. Van a encontrarlo en segundos.'::text),
(299759,33307,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cachette parfaite : une main dépasse. Ils ... le trouver en quelques secondes.'::text,'vont'::text,NULL::text,NULL::text,'Cachette parfaite : une main dépasse. Ils vont le trouver en quelques secondes.'::text),
(299762,33307,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kusursuz saklanma: bir el dışarıda. Onu saniyeler içinde ...'::text,'bulacaklar'::text,'bulacaklar'::text,NULL::text,'Kusursuz saklanma: bir el dışarıda. Onu saniyeler içinde bulacaklar.'::text),
(299763,33307,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hibátlan bújócska: kilóg egy kéz. Pár másodperc alatt meg ... találni.'::text,'fogják'::text,'fogják'::text,NULL::text,'Hibátlan bújócska: kilóg egy kéz. Pár másodperc alatt meg fogják találni.'::text),
(299766,33308,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ist eine Überraschungsparty, klar, also ... sich jeder hinter dem Sofa verstecken.'::text,'muss'::text,'muss'::text,'sollte'::text,'Es ist eine Überraschungsparty, klar, also muss sich jeder hinter dem Sofa verstecken.'::text),
(299770,33308,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це ж вечірка-сюрприз, звісно, тож кожен ... сховатися за диваном.'::text,'має'::text,'мусить'::text,'мав би'::text,'Це ж вечірка-сюрприз, звісно, тож кожен має сховатися за диваном.'::text),
(299769,33308,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es una fiesta sorpresa, claro, así que todo el mundo ... esconderse detrás del sofá.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Es una fiesta sorpresa, claro, así que todo el mundo tiene que esconderse detrás del sofá.'::text),
(299768,33308,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'C''est une fête surprise, évidemment, donc tout le monde ... se cacher derrière le canapé.'::text,'doit'::text,'doit'::text,'devrait'::text,'C''est une fête surprise, évidemment, donc tout le monde doit se cacher derrière le canapé.'::text),
(299771,33308,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sürpriz parti tabii, bu yüzden herkes kanepenin arkasına ...'::text,'saklanmak zorunda'::text,'saklanmalı'::text,'saklanmalı'::text,'Sürpriz parti tabii, bu yüzden herkes kanepenin arkasına saklanmak zorunda.'::text),
(299772,33308,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meglepetésbuli, persze, úgyhogy mindenkinek a kanapé mögé ... bújnia.'::text,'kell'::text,'kell'::text,'kellene'::text,'Meglepetésbuli, persze, úgyhogy mindenkinek a kanapé mögé kell bújnia.'::text),
(299775,33309,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, du ... dich besser verstecken, die Hand ist voll sus.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Alter, du solltest dich besser verstecken, die Hand ist voll sus.'::text),
(299779,33309,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ти ... краще ховатися, ця рука якась підозріла.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Бро, ти мав би краще ховатися, ця рука якась підозріла.'::text),
(299778,33309,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... esconderte mejor, esa mano es un poco sospechosa.'::text,'deberías'::text,'deberías'::text,'deberías'::text,'Tío, deberías esconderte mejor, esa mano es un poco sospechosa.'::text),
(299777,33309,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, tu ... mieux te cacher, cette main est un peu louche.'::text,'devrais'::text,'devrais'::text,'devrais'::text,'Frérot, tu devrais mieux te cacher, cette main est un peu louche.'::text),
(299780,33309,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, daha iyi ..., o el biraz şüpheli.'::text,'saklanmalısın'::text,'saklanmalısın'::text,'saklanmalısın'::text,'Kanka, daha iyi saklanmalısın, o el biraz şüpheli.'::text),
(299781,33309,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, jobban ... elbújnod, az a kéz elég gyanús.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Tesó, jobban kellene elbújnod, az a kéz elég gyanús.'::text),
(299784,33310,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er versucht sich unterm Schreibtisch zu verstecken, ... er grinst, lol.'::text,'aber'::text,'also'::text,'weil'::text,'Yo, er versucht sich unterm Schreibtisch zu verstecken, aber er grinst, lol.'::text),
(299788,33310,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, він пробує сховатися під столом, ... шкіриться, лол.'::text,'але'::text,'тому'::text,'бо'::text,'Йо, він пробує сховатися під столом, але шкіриться, лол.'::text),
(299787,33310,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, intenta esconderse debajo de la mesa, ... está sonriendo, jaja.'::text,'pero'::text,'así que'::text,'porque'::text,'Tío, intenta esconderse debajo de la mesa, pero está sonriendo, jaja.'::text),
(299786,33310,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, il essaie de se cacher sous le bureau, ... il sourit jusqu''aux oreilles, mdr.'::text,'mais'::text,'donc'::text,'parce que'::text,'Wesh, il essaie de se cacher sous le bureau, mais il sourit jusqu''aux oreilles, mdr.'::text),
(299789,33310,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, masanın altına saklanmaya çalışıyor ... sırıtıyor, lol.'::text,'ama'::text,'bu yüzden'::text,'çünkü'::text,'Kanka, masanın altına saklanmaya çalışıyor ama sırıtıyor, lol.'::text),
(299790,33310,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, megpróbál elbújni az asztal alatt, ... vigyorog, lol.'::text,'de'::text,'ezért'::text,'mert'::text,'Figyu, megpróbál elbújni az asztal alatt, de vigyorog, lol.'::text),
(301935,33549,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Ende ... sie einen kleinen Metallschlüssel in der Hand.'::text,'hat'::text,'haben'::text,'ist'::text,'Am Ende hat sie einen kleinen Metallschlüssel in der Hand.'::text),
(301939,33549,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Наприкінці вона ... в руці маленький металевий ключ.'::text,'має'::text,'мати'::text,'є'::text,'Наприкінці вона має в руці маленький металевий ключ.'::text),
(301938,33549,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al final ... una pequeña llave de metal en la mano.'::text,'tiene'::text,'tienen'::text,'está'::text,'Al final tiene una pequeña llave de metal en la mano.'::text),
(301937,33549,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À la fin, elle ... une petite clé en métal dans la main.'::text,'a'::text,'ont'::text,'est'::text,'À la fin, elle a une petite clé en métal dans la main.'::text),
(301940,33549,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonunda elinde küçük metal bir anahtar ...'::text,'var'::text,'var'::text,NULL::text,'Sonunda elinde küçük metal bir anahtar var.'::text),
(301941,33549,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A végén ... egy kis fémkulcs a kezében.'::text,'van'::text,'van'::text,'van'::text,'A végén van egy kis fémkulcs a kezében.'::text),
(301944,33550,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Alter, sie braucht nächstes Mal zwei ...'::text,'Schlüssel'::text,'Schlüssel'::text,'Schlüssel'::text,'Nee Alter, sie braucht nächstes Mal zwei Schlüssel.'::text),
(301948,33550,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні, бро, наступного разу їй знадобляться два ...'::text,'ключі'::text,'ключ'::text,'ключі'::text,'Ні, бро, наступного разу їй знадобляться два ключі.'::text),
(301947,33550,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, la próxima vez va a necesitar dos ...'::text,'llaves'::text,'llave'::text,'llaves'::text,'Qué va, tío, la próxima vez va a necesitar dos llaves.'::text),
(301946,33550,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non frérot, la prochaine fois elle aura besoin de deux ...'::text,'clés'::text,'clé'::text,'clés'::text,'Non frérot, la prochaine fois elle aura besoin de deux clés.'::text),
(301949,33550,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, bir dahaki sefere ona iki ... lazım olacak.'::text,'anahtar'::text,'anahtar'::text,'anahtarlar'::text,'Yok kanka, bir dahaki sefere ona iki anahtar lazım olacak.'::text),
(301950,33550,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem, tesó, legközelebb két ... lesz szüksége.'::text,'kulcsra'::text,'kulcsra'::text,'kulcsra'::text,'Nem, tesó, legközelebb két kulcsra lesz szüksége.'::text),
(301962,33552,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Schlüssel ist in ihrer Hand, also hat ihre Hand einen Schlüssel.'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Dieser Schlüssel ist in ihrer Hand, also hat ihre Hand einen Schlüssel.'::text),
(301966,33552,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ключ у неї в руці, тож її рука має ключ.'::text,'Цей'::text,'Ці'::text,'Ті'::text,'Цей ключ у неї в руці, тож її рука має ключ.'::text),
(301965,33552,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... llave está en su mano, así que su mano tiene una llave.'::text,'Esta'::text,'Estas'::text,'Esas'::text,'Esta llave está en su mano, así que su mano tiene una llave.'::text),
(301964,33552,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... clé est dans sa main, donc sa main a une clé.'::text,'Cette'::text,'Ces'::text,'Ces'::text,'Cette clé est dans sa main, donc sa main a une clé.'::text),
(301967,33552,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... anahtar onun elinde, yani elinin bir anahtarı var.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu anahtar onun elinde, yani elinin bir anahtarı var.'::text),
(301968,33552,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a kulcs a kezében van, tehát a kezének van egy kulcsa.'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Ez a kulcs a kezében van, tehát a kezének van egy kulcsa.'::text),
(301971,33553,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du findest ... Schlüssel unter der Wäsche? Bin schon beeindruckt.'::text,'deinen'::text,'dich'::text,'deinen'::text,'Du findest deinen Schlüssel unter der Wäsche? Bin schon beeindruckt.'::text),
(301975,33553,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти знаходиш ... ключ під білизною? Я аж вражена.'::text,'свій'::text,'свій'::text,'свій'::text,'Ти знаходиш свій ключ під білизною? Я аж вражена.'::text),
(301974,33553,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Encuentras ... llave debajo de la ropa sucia? Me has impresionado un poco.'::text,'tu'::text,'te'::text,'la tuya'::text,'¿Encuentras tu llave debajo de la ropa sucia? Me has impresionado un poco.'::text),
(301973,33553,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu trouves ... clé sous le linge ? Je suis un peu impressionnée.'::text,'ta'::text,'te'::text,'la tienne'::text,'Tu trouves ta clé sous le linge ? Je suis un peu impressionnée.'::text),
(301976,33553,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... anahtarını çamaşırların altında mı buluyorsun? Biraz etkilendim.'::text,'Senin'::text,'Sen'::text,'Seninki'::text,'Senin anahtarını çamaşırların altında mı buluyorsun? Biraz etkilendim.'::text),
(301977,33553,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megtalálod a ... a szennyes alatt? Kicsit le vagyok nyűgözve.'::text,'kulcsodat'::text,'téged'::text,'a tiédet'::text,'Megtalálod a kulcsodat a szennyes alatt? Kicsit le vagyok nyűgözve.'::text),
(301980,33554,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du wühlst dich durch so viel ... für einen kleinen Schlüssel.'::text,'Wäsche'::text,'Wäsche'::text,'eine Wäsche'::text,'Ehrlich, du wühlst dich durch so viel Wäsche für einen kleinen Schlüssel.'::text),
(301984,33554,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти перебираєш стільки ... заради одного маленького ключа.'::text,'білизни'::text,'білизни'::text,'білизни'::text,'Чесно, ти перебираєш стільки білизни заради одного маленького ключа.'::text),
(301983,33554,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, rebuscas entre tanta ... por una llave pequeña.'::text,'ropa'::text,'ropa'::text,'una ropa'::text,'En serio, rebuscas entre tanta ropa por una llave pequeña.'::text),
(301982,33554,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu fouilles dans tellement de ... pour une petite clé.'::text,'linge'::text,'linge'::text,'un linge'::text,'Franchement, tu fouilles dans tellement de linge pour une petite clé.'::text),
(301985,33554,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, küçük bir anahtar için o kadar çok ... karıştırıyorsun.'::text,'çamaşır'::text,'çamaşırlar'::text,'bir çamaşır'::text,'Açıkçası, küçük bir anahtar için o kadar çok çamaşır karıştırıyorsun.'::text),
(301986,33554,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, ennyi ... túrsz át egyetlen kis kulcsért.'::text,'szennyest'::text,'szennyest'::text,'egy szennyest'::text,'Őszintén, ennyi szennyest túrsz át egyetlen kis kulcsért.'::text),
(301998,33556,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... ein kleiner Schlüssel unter dem Kleiderhaufen.'::text,'ist'::text,'sind'::text,'sein'::text,'Da ist ein kleiner Schlüssel unter dem Kleiderhaufen.'::text),
(302002,33556,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Під купою одягу ... маленький ключ.'::text,'є'::text,'є'::text,'бути'::text,'Під купою одягу є маленький ключ.'::text),
(302001,33556,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una llave pequeña debajo del montón de ropa.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay una llave pequeña debajo del montón de ropa.'::text),
(302000,33556,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... une petite clé sous le tas de vêtements.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a une petite clé sous le tas de vêtements.'::text),
(302003,33556,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kıyafet yığınının altında küçük bir anahtar ...'::text,'var'::text,'var'::text,'olmak'::text,'Kıyafet yığınının altında küçük bir anahtar var.'::text),
(302004,33556,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ruhakupac alatt ... egy kis kulcs.'::text,'van'::text,'vannak'::text,'lenni'::text,'A ruhakupac alatt van egy kis kulcs.'::text),
(328179,36465,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr entspannend, klar. Der Teenager ... an einem alten Automotor.'::text,'arbeitet'::text,'arbeitet'::text,'arbeitet'::text,'Sehr entspannend, klar. Der Teenager arbeitet an einem alten Automotor.'::text),
(328183,36465,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже розслабляє, звісно. Підліток ... над старим двигуном машини.'::text,'працює'::text,'працює'::text,'працює'::text,'Дуже розслабляє, звісно. Підліток працює над старим двигуном машини.'::text),
(328182,36465,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy relajante, claro. El adolescente ... en un viejo motor de coche.'::text,'está trabajando'::text,'trabaja'::text,'está trabajando'::text,'Muy relajante, claro. El adolescente está trabajando en un viejo motor de coche.'::text),
(328181,36465,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très relaxant, évidemment. L''ado ... sur un vieux moteur de voiture.'::text,'est en train de travailler'::text,'travaille'::text,'est en train de travailler'::text,'Très relaxant, évidemment. L''ado est en train de travailler sur un vieux moteur de voiture.'::text),
(328184,36465,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok rahatlatıcı, belli. Genç, eski bir araba motoru üzerinde ...'::text,'çalışıyor'::text,'çalışır'::text,'çalışıyor'::text,'Çok rahatlatıcı, belli. Genç, eski bir araba motoru üzerinde çalışıyor.'::text),
(328185,36465,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon pihentető, persze. A tinédzser egy régi autómotoron ...'::text,'dolgozik'::text,'dolgozik'::text,'dolgozik'::text,'Nagyon pihentető, persze. A tinédzser egy régi autómotoron dolgozik.'::text),
(328188,36466,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Leichter Job, eindeutig. Gerade ... sie an einem Holzstuhl.'::text,'arbeitet'::text,'arbeitet'::text,NULL::text,'Leichter Job, eindeutig. Gerade arbeitet sie an einem Holzstuhl.'::text),
(328192,36466,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Легка робота, явно. Саме зараз вона ... над дерев''яним стільцем.'::text,'працює'::text,'працює'::text,NULL::text,'Легка робота, явно. Саме зараз вона працює над дерев''яним стільцем.'::text),
(328191,36466,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trabajo fácil, está claro. Ahora mismo ... en una silla de madera.'::text,'está trabajando'::text,'trabaja'::text,NULL::text,'Trabajo fácil, está claro. Ahora mismo está trabajando en una silla de madera.'::text),
(328190,36466,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boulot facile, clairement. En ce moment, elle ... sur une chaise en bois.'::text,'est en train de travailler'::text,'travaille'::text,NULL::text,'Boulot facile, clairement. En ce moment, elle est en train de travailler sur une chaise en bois.'::text),
(328193,36466,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kolay iş, belli. Şu an ahşap bir sandalye üzerinde ...'::text,'çalışıyor'::text,'çalışır'::text,NULL::text,'Kolay iş, belli. Şu an ahşap bir sandalye üzerinde çalışıyor.'::text),
(328194,36466,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Könnyű meló, egyértelműen. Épp most egy faszéken ...'::text,'dolgozik'::text,'dolgozik'::text,NULL::text,'Könnyű meló, egyértelműen. Épp most egy faszéken dolgozik.'::text),
(328197,36467,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... die ganze Nacht an dem Auto arbeiten, ehrlich.'::text,'wird'::text,'ist'::text,'wird'::text,'Alter, er wird die ganze Nacht an dem Auto arbeiten, ehrlich.'::text),
(328201,36467,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він ... працювати над тією машиною всю ніч, чесно.'::text,'буде'::text,'є'::text,'збирається'::text,'Бро, він буде працювати над тією машиною всю ніч, чесно.'::text),
(328200,36467,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... trabajar en ese coche toda la noche, te lo juro.'::text,''::text,'está'::text,'va a'::text,'Tío, trabajar en ese coche toda la noche, te lo juro.'::text),
(328199,36467,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il ... bosser sur cette voiture toute la nuit, sans mentir.'::text,''::text,'est'::text,'va'::text,'Frérot, il bosser sur cette voiture toute la nuit, sans mentir.'::text),
(328202,36467,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bütün gece o araba üzerinde ..., cidden.'::text,'çalışacak'::text,NULL::text,'çalışacak'::text,'Kanka, bütün gece o araba üzerinde çalışacak, cidden.'::text),
(328203,36467,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, egész éjjel azon az autón ... dolgozni, komolyan.'::text,'fog'::text,'van'::text,'fog'::text,'Tesó, egész éjjel azon az autón fog dolgozni, komolyan.'::text),
(328215,36469,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap: Sie ... an 10 alten Handys arbeiten.'::text,'wird'::text,'wird'::text,NULL::text,'Roadmap: Sie wird an 10 alten Handys arbeiten.'::text),
(328219,36469,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дорожня карта: вона ... працювати над 10 старими телефонами.'::text,'збирається'::text,'буде'::text,NULL::text,'Дорожня карта: вона збирається працювати над 10 старими телефонами.'::text),
(328218,36469,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoja de ruta: ... trabajar en 10 móviles viejos.'::text,'va a'::text,NULL::text,NULL::text,'Hoja de ruta: va a trabajar en 10 móviles viejos.'::text),
(328217,36469,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap : elle ... travailler sur 10 vieux téléphones.'::text,'va'::text,NULL::text,NULL::text,'Roadmap : elle va travailler sur 10 vieux téléphones.'::text),
(328220,36469,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yol haritası: 10 eski telefon üzerinde ...'::text,'çalışacak'::text,'çalışacak'::text,NULL::text,'Yol haritası: 10 eski telefon üzerinde çalışacak.'::text),
(328221,36469,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ütemterv: 10 régi telefonon ... dolgozni.'::text,'fog'::text,'fog'::text,NULL::text,'Ütemterv: 10 régi telefonon fog dolgozni.'::text),
(328224,36470,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Auto ist kaputt, also ... er daran arbeiten. Es ist kaputt.'::text,'muss'::text,'muss'::text,'sollte'::text,'Das Auto ist kaputt, also muss er daran arbeiten. Es ist kaputt.'::text),
(328228,36470,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Машина зламана, тож він ... над нею працювати. Вона зламана.'::text,'має'::text,'мусить'::text,'мав би'::text,'Машина зламана, тож він має над нею працювати. Вона зламана.'::text),
(328227,36470,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El coche está roto, así que ... trabajar en él. Está roto.'::text,'tiene que'::text,'debe'::text,'debería'::text,'El coche está roto, así que tiene que trabajar en él. Está roto.'::text),
(328226,36470,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La voiture est en panne, donc il ... travailler dessus. Elle est en panne.'::text,'doit'::text,'doit'::text,'devrait'::text,'La voiture est en panne, donc il doit travailler dessus. Elle est en panne.'::text),
(328229,36470,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Araba bozuk, bu yüzden onun üzerinde ... – bozuk ya.'::text,'çalışmak zorunda'::text,'çalışmalı'::text,'çalışmalı'::text,'Araba bozuk, bu yüzden onun üzerinde çalışmak zorunda – bozuk ya.'::text),
(328230,36470,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az autó elromlott, ezért ... dolgoznia rajta. El van romolva.'::text,'kell'::text,'kell'::text,'kellene'::text,'Az autó elromlott, ezért kell dolgoznia rajta. El van romolva.'::text),
(328233,36471,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie arbeitet mit einer Bohrmaschine, also ... sie eine Brille tragen.'::text,'sollte'::text,'soll'::text,'sollte'::text,'Sie arbeitet mit einer Bohrmaschine, also sollte sie eine Brille tragen.'::text),
(328237,36471,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона працює з дрилем, тож вона ... носити окуляри.'::text,'мала б'::text,'буде'::text,'мала б'::text,'Вона працює з дрилем, тож вона мала б носити окуляри.'::text),
(328236,36471,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trabaja con un taladro, así que ... llevar gafas.'::text,'debería'::text,'deberá'::text,'debería'::text,'Trabaja con un taladro, así que debería llevar gafas.'::text),
(328235,36471,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle travaille avec une perceuse, donc elle ... porter des lunettes.'::text,'devrait'::text,'devra'::text,'devrait'::text,'Elle travaille avec une perceuse, donc elle devrait porter des lunettes.'::text),
(328238,36471,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Matkapla çalışıyor, bu yüzden gözlük ...'::text,'takmalı'::text,'takacak'::text,'takmalı'::text,'Matkapla çalışıyor, bu yüzden gözlük takmalı.'::text),
(328239,36471,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Fúróval dolgozik, ezért szemüveget ... viselnie.'::text,'kellene'::text,'kell'::text,'kellene'::text,'Fúróval dolgozik, ezért szemüveget kellene viselnie.'::text),
(328242,36472,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er arbeitet an dem alten Auto, ... er es reparieren will.'::text,'weil'::text,'aber'::text,'also'::text,'Er arbeitet an dem alten Auto, weil er es reparieren will.'::text),
(328246,36472,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він працює над старою машиною, ... хоче її полагодити.'::text,'бо'::text,'але'::text,'тому'::text,'Він працює над старою машиною, бо хоче її полагодити.'::text),
(328245,36472,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Trabaja en el coche viejo ... quiere arreglarlo.'::text,'porque'::text,'pero'::text,'así que'::text,'Trabaja en el coche viejo porque quiere arreglarlo.'::text),
(328244,36472,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il travaille sur la vieille voiture ... il veut la réparer.'::text,'parce que'::text,'mais'::text,'donc'::text,'Il travaille sur la vieille voiture parce que il veut la réparer.'::text),
(328247,36472,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eski araba üzerinde çalışıyor ... onu tamir etmek istiyor.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Eski araba üzerinde çalışıyor çünkü onu tamir etmek istiyor.'::text),
(328248,36472,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A régi autón dolgozik, ... meg akarja javítani.'::text,'mert'::text,'de'::text,'ezért'::text,'A régi autón dolgozik, mert meg akarja javítani.'::text),
(320394,35600,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schau! Das Hausgerüst ... noch keine Wände! Eine Katastrophe!'::text,'hat'::text,'haben'::text,'hat'::text,'Schau! Das Hausgerüst hat noch keine Wände! Eine Katastrophe!'::text),
(320398,35600,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дивись! Каркас будинку ще не ... стін! Катастрофа!'::text,'має'::text,'мати'::text,'має'::text,'Дивись! Каркас будинку ще не має стін! Катастрофа!'::text),
(320397,35600,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Mira! ¡La estructura de la casa aún no ... paredes! ¡Un desastre!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Mira! ¡La estructura de la casa aún no tiene paredes! ¡Un desastre!'::text),
(320396,35600,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regarde ! La structure de la maison ... encore aucun mur ! Une catastrophe !'::text,'n''a'::text,'n''ont'::text,'n''a'::text,'Regarde ! La structure de la maison n''a encore aucun mur ! Une catastrophe !'::text),
(320399,35600,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bak! Evin iskeletinin henüz hiç duvarı ...! Felaket!'::text,'yok'::text,'yok'::text,'yok'::text,'Bak! Evin iskeletinin henüz hiç duvarı yok! Felaket!'::text),
(320400,35600,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nézd! A ház vázának még ... egy fala sem! Katasztrófa!'::text,'nincs'::text,'nincs'::text,'nincs'::text,'Nézd! A ház vázának még nincs egy fala sem! Katasztrófa!'::text),
(320403,35601,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Acht ... heben eine riesige Holzkonstruktion hoch! Total verrückt!'::text,'Personen'::text,'Personen'::text,'Person'::text,'Acht Personen heben eine riesige Holzkonstruktion hoch! Total verrückt!'::text),
(320407,35601,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вісім ... піднімають одну величезну дерев''яну конструкцію! Просто божевілля!'::text,'людей'::text,'людей'::text,'людина'::text,'Вісім людей піднімають одну величезну дерев''яну конструкцію! Просто божевілля!'::text),
(320406,35601,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ocho ... levantan una enorme estructura de madera! ¡Una locura total!'::text,'personas'::text,'personas'::text,'persona'::text,'¡Ocho personas levantan una enorme estructura de madera! ¡Una locura total!'::text),
(320405,35601,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Huit ... soulèvent une énorme structure en bois ! Complètement fou !'::text,'personnes'::text,'personnes'::text,'personne'::text,'Huit personnes soulèvent une énorme structure en bois ! Complètement fou !'::text),
(320408,35601,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sekiz ... kocaman bir ahşap yapıyı kaldırıyor! Tamamen çılgınlık!'::text,'kişi'::text,'kişiler'::text,'kişi'::text,'Sekiz kişi kocaman bir ahşap yapıyı kaldırıyor! Tamamen çılgınlık!'::text),
(320409,35601,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyolc ... emel fel egy hatalmas faszerkezetet! Teljesen őrület!'::text,'ember'::text,'ember'::text,'ember'::text,'Nyolc ember emel fel egy hatalmas faszerkezetet! Teljesen őrület!'::text),
(320412,35602,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das ist kein Spielzeug! Das ist ... riesige Holzkonstruktion!'::text,'eine'::text,'eine'::text,'die'::text,'Das ist kein Spielzeug! Das ist eine riesige Holzkonstruktion!'::text),
(320416,35602,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Це не іграшка! Це ... величезна дерев''яна конструкція!'::text,''::text,NULL::text,NULL::text,'Це не іграшка! Це величезна дерев''яна конструкція!'::text),
(320415,35602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No es un juguete! ¡Es ... enorme estructura de madera!'::text,'una'::text,'una'::text,'la'::text,'¡No es un juguete! ¡Es una enorme estructura de madera!'::text),
(320414,35602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce n''est pas un jouet ! C''est ... énorme structure en bois !'::text,'une'::text,'une'::text,'l'''::text,'Ce n''est pas un jouet ! C''est une énorme structure en bois !'::text),
(320417,35602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu bir oyuncak değil! Bu ... dev ahşap yapı!'::text,'bir'::text,'bir'::text,NULL::text,'Bu bir oyuncak değil! Bu bir dev ahşap yapı!'::text),
(320418,35602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ez nem játék! Ez ... hatalmas faszerkezet!'::text,'egy'::text,'egy'::text,'a'::text,'Ez nem játék! Ez egy hatalmas faszerkezet!'::text),
(320430,35604,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann zeigt ... kleine Konstruktion, ein Vogelhaus.'::text,'seine'::text,'ihre'::text,'seine'::text,'Der Mann zeigt seine kleine Konstruktion, ein Vogelhaus.'::text),
(320434,35604,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік показує ... невелику конструкцію — шпаківню.'::text,'свою'::text,'свою'::text,'свою'::text,'Чоловік показує свою невелику конструкцію — шпаківню.'::text),
(320433,35604,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre enseña ... pequeña estructura, una casita para pájaros.'::text,'su'::text,'su'::text,'su'::text,'El hombre enseña su pequeña estructura, una casita para pájaros.'::text),
(320432,35604,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme montre ... petite structure, un nichoir.'::text,'sa'::text,'sa'::text,'sa'::text,'L''homme montre sa petite structure, un nichoir.'::text),
(320435,35604,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adam ... küçük yapısını, bir kuş evini gösteriyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Adam onun küçük yapısını, bir kuş evini gösteriyor.'::text),
(320436,35604,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A férfi megmutatja a kis ..., egy madárodút.'::text,'szerkezetét'::text,'szerkezetét'::text,'szerkezetét'::text,'A férfi megmutatja a kis szerkezetét, egy madárodút.'::text),
(320448,35606,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie benutzen ... lange Bretter für die Holzkonstruktion.'::text,'viele'::text,'viel'::text,'ein bisschen'::text,'Sie benutzen viele lange Bretter für die Holzkonstruktion.'::text),
(320452,35606,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони використовують ... довгих дощок для дерев''яної конструкції.'::text,'багато'::text,'багато'::text,'трохи'::text,'Вони використовують багато довгих дощок для дерев''яної конструкції.'::text),
(320451,35606,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Usan ... tablas largas para la estructura de madera.'::text,'muchas'::text,'mucha'::text,'un poco de'::text,'Usan muchas tablas largas para la estructura de madera.'::text),
(320450,35606,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ils utilisent ... longues planches pour la structure en bois.'::text,'beaucoup de'::text,'beaucoup de'::text,'un peu de'::text,'Ils utilisent beaucoup de longues planches pour la structure en bois.'::text),
(320453,35606,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahşap yapı için ... uzun tahta kullanıyorlar.'::text,'birçok'::text,'çok'::text,'biraz'::text,'Ahşap yapı için birçok uzun tahta kullanıyorlar.'::text),
(320454,35606,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hosszú deszkát használnak a faszerkezethez.'::text,'Sok'::text,'Sok'::text,'Egy kis'::text,'Sok hosszú deszkát használnak a faszerkezethez.'::text),
(320457,35607,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... eine Konstruktion auf dem Rasen, weil sie sie dort gebaut haben.'::text,'ist'::text,'sind'::text,'sein'::text,'Da ist eine Konstruktion auf dem Rasen, weil sie sie dort gebaut haben.'::text),
(320461,35607,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'На траві ... конструкція, бо вони її там збудували.'::text,'є'::text,'є'::text,'бути'::text,'На траві є конструкція, бо вони її там збудували.'::text),
(320460,35607,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una estructura en el césped porque la construyeron ahí.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay una estructura en el césped porque la construyeron ahí.'::text),
(320459,35607,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... une structure sur la pelouse parce qu''ils l''ont construite là.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a une structure sur la pelouse parce qu''ils l''ont construite là.'::text),
(320462,35607,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çimenlerin üstünde bir yapı ... çünkü onu oraya yaptılar.'::text,'var'::text,'var'::text,'olmak'::text,'Çimenlerin üstünde bir yapı var çünkü onu oraya yaptılar.'::text),
(320463,35607,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A füvön ... egy szerkezet, mert oda építették.'::text,'van'::text,'vannak'::text,'lenni'::text,'A füvön van egy szerkezet, mert oda építették.'::text),
(298461,33163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein langes Messer ... eine Wassermelone halbieren.'::text,'kann'::text,'kann'::text,'kann'::text,'Ein langes Messer kann eine Wassermelone halbieren.'::text),
(298465,33163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Один довгий ніж ... розрізати кавун навпіл.'::text,'може'::text,'може'::text,'може'::text,'Один довгий ніж може розрізати кавун навпіл.'::text),
(298464,33163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un cuchillo largo ... cortar una sandía por la mitad.'::text,'puede'::text,'puede'::text,'puede'::text,'Un cuchillo largo puede cortar una sandía por la mitad.'::text),
(298463,33163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un long couteau ... couper une pastèque en deux.'::text,'peut'::text,'peut'::text,'peut'::text,'Un long couteau peut couper une pastèque en deux.'::text),
(298466,33163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uzun bir bıçak bir karpuzu ikiye ...'::text,'bölebilir'::text,'bölebilir'::text,'bölebilir'::text,'Uzun bir bıçak bir karpuzu ikiye bölebilir.'::text),
(298467,33163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy hosszú kés ... egy görögdinnyét.'::text,'kettévághat'::text,'kettévághat'::text,'kettévághat'::text,'Egy hosszú kés kettévághat egy görögdinnyét.'::text),
(298470,33164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kürbis liegt offen in zwei ...'::text,'Hälften'::text,'Hälften'::text,'Hälfte'::text,'Der Kürbis liegt offen in zwei Hälften.'::text),
(298474,33164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гарбуз лежить розкритий на дві ...'::text,'половини'::text,'половини'::text,'половину'::text,'Гарбуз лежить розкритий на дві половини.'::text),
(298473,33164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La calabaza está abierta en dos ...'::text,'mitades'::text,'mitades'::text,'mitad'::text,'La calabaza está abierta en dos mitades.'::text),
(298472,33164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La citrouille est ouverte en deux ...'::text,'moitiés'::text,'moitiés'::text,'moitié'::text,'La citrouille est ouverte en deux moitiés.'::text),
(298475,33164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balkabağı iki ... hâlinde açık duruyor.'::text,'yarı'::text,'yarılar'::text,'yarı'::text,'Balkabağı iki yarı hâlinde açık duruyor.'::text),
(298476,33164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tök két ... nyílva fekszik.'::text,'félre'::text,'félre'::text,'félre'::text,'A tök két félre nyílva fekszik.'::text),
(298479,33165,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Mann schneidet die Wassermelone ... der Mitte durch.'::text,'in'::text,'auf'::text,'an'::text,'Der Mann schneidet die Wassermelone in der Mitte durch.'::text),
(298483,33165,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чоловік розрізає кавун ... дві половини.'::text,'на'::text,'на'::text,'біля'::text,'Чоловік розрізає кавун на дві половини.'::text),
(298482,33165,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El hombre corta la sandía ... la mitad.'::text,'por'::text,'sobre'::text,'a'::text,'El hombre corta la sandía por la mitad.'::text),
(298481,33165,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''homme coupe la pastèque ... deux.'::text,'en'::text,'sur'::text,'à'::text,'L''homme coupe la pastèque en deux.'::text),
