(297833,33093,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un petit plan : l''année prochaine, elle ... faire pousser dix citrouilles géantes.'::text,'va'::text,'vont'::text,'va'::text,'Clairement un petit plan : l''année prochaine, elle va faire pousser dix citrouilles géantes.'::text),
(297836,33093,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki ufak bir plan: seneye on dev balkabağı ...'::text,'yetiştirecek'::text,'yetiştirecekler'::text,'yetiştirecek'::text,'Belli ki ufak bir plan: seneye on dev balkabağı yetiştirecek.'::text),
(297837,33093,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyértelműen kicsi terv: jövőre tíz óriási tököt ... termeszteni.'::text,'fog'::text,'fognak'::text,'fog'::text,'Egyértelműen kicsi terv: jövőre tíz óriási tököt fog termeszteni.'::text),
(297840,33094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Dieser Kürbis ... größer als das ganze Haus werden!'::text,'wird'::text,'wird'::text,NULL::text,'Katastrophe! Dieser Kürbis wird größer als das ganze Haus werden!'::text),
(297844,33094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Цей гарбуз ... вирости більшим за весь будинок!'::text,'збирається'::text,'буде'::text,NULL::text,'Катастрофа! Цей гарбуз збирається вирости більшим за весь будинок!'::text),
(297843,33094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Esa calabaza ... crecer más que toda la casa!'::text,'va a'::text,NULL::text,NULL::text,'¡Desastre! ¡Esa calabaza va a crecer más que toda la casa!'::text),
(297842,33094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Cette citrouille ... devenir plus grande que toute la maison !'::text,'va'::text,NULL::text,NULL::text,'Catastrophe ! Cette citrouille va devenir plus grande que toute la maison !'::text),
(297845,33094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! O balkabağı bütün evden daha büyük ...!'::text,'olacak'::text,'olacak'::text,NULL::text,'Felaket! O balkabağı bütün evden daha büyük olacak!'::text),
(297846,33094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Az a tök nagyobbra ... nőni, mint az egész ház!'::text,'fog'::text,'fog'::text,NULL::text,'Katasztrófa! Az a tök nagyobbra fog nőni, mint az egész ház!'::text),
(297849,33095,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ich ... den größten Kürbis aller Zeiten züchten! Alles andere ist eine Katastrophe!'::text,'muss'::text,'muss'::text,'sollte'::text,'Ich muss den größten Kürbis aller Zeiten züchten! Alles andere ist eine Katastrophe!'::text),
(297853,33095,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Я ... виростити найбільший гарбуз в історії! Усе менше — катастрофа!'::text,'мушу'::text,'маю'::text,'мала б'::text,'Я мушу виростити найбільший гарбуз в історії! Усе менше — катастрофа!'::text),
(297852,33095,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... cultivar la calabaza más grande de la historia! ¡Cualquier cosa menos es un desastre!'::text,'Debo'::text,'Tengo que'::text,'Debería'::text,'¡Debo cultivar la calabaza más grande de la historia! ¡Cualquier cosa menos es un desastre!'::text),
(297851,33095,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je ... faire pousser la plus grosse citrouille de tous les temps ! Tout le reste est un désastre !'::text,'dois'::text,'dois'::text,'devrais'::text,'Je dois faire pousser la plus grosse citrouille de tous les temps ! Tout le reste est un désastre !'::text),
(297854,33095,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gelmiş geçmiş en büyük balkabağını ...! Daha azı felaket!'::text,'yetiştirmeliyim'::text,'yetiştirmek zorundayım'::text,'yetiştirmeliyim'::text,'Gelmiş geçmiş en büyük balkabağını yetiştirmeliyim! Daha azı felaket!'::text),
(297855,33095,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A valaha volt legnagyobb tököt ... termesztenem! Minden más katasztrófa!'::text,'kell'::text,'kell'::text,'kellene'::text,'A valaha volt legnagyobb tököt kell termesztenem! Minden más katasztrófa!'::text),
(297867,33097,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also anscheinend ist ihr Kürbis riesig geworden, ... sie ihn täglich gegossen hat.'::text,'weil'::text,'aber'::text,'also'::text,'Okay, also anscheinend ist ihr Kürbis riesig geworden, weil sie ihn täglich gegossen hat.'::text),
(297871,33097,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, її гарбуз нібито виріс величезним, ... вона поливала його щодня.'::text,'бо'::text,'але'::text,'тому'::text,'Коротше, її гарбуз нібито виріс величезним, бо вона поливала його щодня.'::text),
(297870,33097,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues al parecer su calabaza creció muchísimo ... la regaba a diario.'::text,'porque'::text,'pero'::text,'así que'::text,'Vale, pues al parecer su calabaza creció muchísimo porque la regaba a diario.'::text),
(297869,33097,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment sa citrouille est devenue énorme ... elle l''arrosait tous les jours.'::text,'parce que'::text,'mais'::text,'donc'::text,'Bon alors, apparemment sa citrouille est devenue énorme parce que elle l''arrosait tous les jours.'::text),
(297872,33097,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, meğer onun balkabağı kocaman olmuş ... her gün suluyormuş.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Tamam, meğer onun balkabağı kocaman olmuş çünkü her gün suluyormuş.'::text),
(297873,33097,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag hatalmasra nőtt a tökje, ... minden nap locsolta.'::text,'mert'::text,'de'::text,'ezért'::text,'Oké, szóval állítólag hatalmasra nőtt a tökje, mert minden nap locsolta.'::text),
(320718,35636,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Sommer ... die Fensterbank zwei Töpfe mit Kräutern.'::text,'hat'::text,'haben'::text,'hat'::text,'Im Sommer hat die Fensterbank zwei Töpfe mit Kräutern.'::text),
(320722,35636,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Улітку підвіконня ... два горщики з травами.'::text,'має'::text,'мати'::text,'має'::text,'Улітку підвіконня має два горщики з травами.'::text),
(320721,35636,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En verano, el alféizar ... dos macetas de hierbas.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'En verano, el alféizar tiene dos macetas de hierbas.'::text),
(320720,35636,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En été, le rebord de fenêtre ... deux pots d''herbes aromatiques.'::text,'a'::text,'ont'::text,'a'::text,'En été, le rebord de fenêtre a deux pots d''herbes aromatiques.'::text),
(320723,35636,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yazın pencere pervazında iki saksı bitki ...'::text,'var'::text,'var'::text,'var'::text,'Yazın pencere pervazında iki saksı bitki var.'::text),
(320724,35636,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyáron az ablakpárkányon ... két cserép fűszernövény.'::text,'van'::text,'van'::text,'van'::text,'Nyáron az ablakpárkányon van két cserép fűszernövény.'::text),
(320727,35637,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jeden Sommer ... die Sonne diese armen Kräuter! Ein Albtraum!'::text,'verbrennt'::text,'verbrennen'::text,'verbrennend'::text,'Jeden Sommer verbrennt die Sonne diese armen Kräuter! Ein Albtraum!'::text),
(320731,35637,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоліта сонце ... ці бідні трави! Жах!'::text,'палить'::text,'палити'::text,'палячи'::text,'Щоліта сонце палить ці бідні трави! Жах!'::text),
(320730,35637,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cada verano el sol ... estas pobres hierbas! ¡Una pesadilla!'::text,'quema'::text,'quemar'::text,'quemando'::text,'¡Cada verano el sol quema estas pobres hierbas! ¡Una pesadilla!'::text),
(320729,35637,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque été, le soleil ... ces pauvres herbes ! Un cauchemar !'::text,'brûle'::text,'brûler'::text,'brûlant'::text,'Chaque été, le soleil brûle ces pauvres herbes ! Un cauchemar !'::text),
(320732,35637,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yaz güneş bu zavallı bitkileri ...! Kâbus!'::text,'yakar'::text,'yakmak'::text,'yakarak'::text,'Her yaz güneş bu zavallı bitkileri yakar! Kâbus!'::text),
(320733,35637,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden nyáron a nap ... ezeket a szegény fűszernövényeket! Rémálom!'::text,'megégeti'::text,'megégetni'::text,'megégető'::text,'Minden nyáron a nap megégeti ezeket a szegény fűszernövényeket! Rémálom!'::text),
(320736,35638,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Sommer ... das arme Gras niemals ohne Wasser leben!'::text,'kann'::text,'kann'::text,'ist'::text,'Im Sommer kann das arme Gras niemals ohne Wasser leben!'::text),
(320740,35638,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Улітку бідна трава ніколи не ... жити без води!'::text,'може'::text,'може'::text,'є'::text,'Улітку бідна трава ніколи не може жити без води!'::text),
(320739,35638,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡En verano, la pobre hierba no ... vivir nunca sin agua!'::text,'puede'::text,'puede'::text,'está'::text,'¡En verano, la pobre hierba no puede vivir nunca sin agua!'::text),
(320738,35638,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En été, la pauvre herbe ne ... jamais vivre sans eau !'::text,'peut'::text,'peut'::text,'est'::text,'En été, la pauvre herbe ne peut jamais vivre sans eau !'::text),
(320741,35638,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yazın zavallı çimen susuz asla ...!'::text,'yaşayamaz'::text,'yaşayamaz'::text,NULL::text,'Yazın zavallı çimen susuz asla yaşayamaz!'::text),
(320742,35638,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyáron a szegény fű soha nem ... élni víz nélkül!'::text,'tud'::text,'tud'::text,'van'::text,'Nyáron a szegény fű soha nem tud élni víz nélkül!'::text),
(320745,35639,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Kinder spielen ... Sommer im Garten.'::text,'im'::text,'am'::text,'um'::text,'Die Kinder spielen im Sommer im Garten.'::text),
(320749,35639,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Діти граються в саду ... літній час.'::text,'у'::text,'на'::text,'о'::text,'Діти граються в саду у літній час.'::text),
(320748,35639,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los niños juegan en el jardín ... verano.'::text,'en'::text,'sobre'::text,'a'::text,'Los niños juegan en el jardín en verano.'::text),
(320747,35639,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les enfants jouent dans le jardin ... été.'::text,'en'::text,'sur'::text,'à'::text,'Les enfants jouent dans le jardin en été.'::text),
(320750,35639,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuklar ... bahçede oynuyor.'::text,'yazın'::text,NULL::text,NULL::text,'Çocuklar yazın bahçede oynuyor.'::text),
(320751,35639,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gyerekek ... a kertben játszanak.'::text,'nyáron'::text,'nyáron'::text,'nyárkor'::text,'A gyerekek nyáron a kertben játszanak.'::text),
(320763,35641,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, ich habe gehört, sie verbrauchen diesen Sommer so viel ... im Garten.'::text,'Wasser'::text,'Wasser'::text,'Tropfen'::text,'Okay, ich habe gehört, sie verbrauchen diesen Sommer so viel Wasser im Garten.'::text),
(320767,35641,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що цього літа вони витрачають стільки ... в саду.'::text,'води'::text,'вод'::text,'крапель'::text,'Коротше, я чула, що цього літа вони витрачають стільки води в саду.'::text),
(320766,35641,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, me han dicho que este verano gastan tanta ... en el jardín.'::text,'agua'::text,'agua'::text,'gotas'::text,'Vale, me han dicho que este verano gastan tanta agua en el jardín.'::text),
(320765,35641,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, on m''a dit qu''ils utilisent tellement ... dans le jardin cet été.'::text,'d''eau'::text,'d''eau'::text,'de gouttes'::text,'Bon, on m''a dit qu''ils utilisent tellement d''eau dans le jardin cet été.'::text),
(320768,35641,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, duydum ki bu yaz bahçede o kadar çok ... kullanıyorlarmış.'::text,'su'::text,'sular'::text,'damla'::text,'Tamam, duydum ki bu yaz bahçede o kadar çok su kullanıyorlarmış.'::text),
(320769,35641,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, azt hallottam, hogy idén nyáron annyi ... használnak a kertben.'::text,'vizet'::text,'vizet'::text,'cseppet'::text,'Oké, azt hallottam, hogy idén nyáron annyi vizet használnak a kertben.'::text),
(320781,35643,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Im Sommer ... da ein Regenbogen im Strahl des Rasensprengers.'::text,'ist'::text,'sind'::text,'sein'::text,'Im Sommer ist da ein Regenbogen im Strahl des Rasensprengers.'::text),
(320785,35643,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Улітку в бризках поливалки ... веселка.'::text,'є'::text,'є'::text,'бути'::text,'Улітку в бризках поливалки є веселка.'::text),
(320784,35643,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En verano ... un arcoíris en el chorro del aspersor.'::text,'hay'::text,'hay'::text,'hay'::text,'En verano hay un arcoíris en el chorro del aspersor.'::text),
(320783,35643,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En été, ... un arc-en-ciel dans le jet de l''arroseur.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'En été, il y a un arc-en-ciel dans le jet de l''arroseur.'::text),
(320786,35643,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yazın fıskiyenin serpintisinde bir gökkuşağı ...'::text,'var'::text,'var'::text,'olmak'::text,'Yazın fıskiyenin serpintisinde bir gökkuşağı var.'::text),
(320787,35643,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyáron ... egy szivárvány a locsoló permetében.'::text,'van'::text,'vannak'::text,'lenni'::text,'Nyáron van egy szivárvány a locsoló permetében.'::text),
(318144,35350,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... er das schwerste Problem der Welt! Absolut!'::text,'löste'::text,'löst'::text,'lösen'::text,'Gestern löste er das schwerste Problem der Welt! Absolut!'::text),
(318148,35350,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора він ... найскладнішу задачу у світі! Абсолютно!'::text,'розв''язав'::text,'розв''язує'::text,'розв''язати'::text,'Учора він розв''язав найскладнішу задачу у світі! Абсолютно!'::text),
(318147,35350,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Ayer ... el problema más difícil del mundo! ¡Totalmente!'::text,'resolvió'::text,'resuelve'::text,'resolver'::text,'¡Ayer resolvió el problema más difícil del mundo! ¡Totalmente!'::text),
(318146,35350,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, il ... le problème le plus difficile du monde ! Absolument !'::text,'a résolu'::text,'résout'::text,'résoudre'::text,'Hier, il a résolu le problème le plus difficile du monde ! Absolument !'::text),
(318149,35350,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün dünyanın en zor problemini ...! Kesinlikle!'::text,'çözdü'::text,'çözer'::text,'çözmek'::text,'Dün dünyanın en zor problemini çözdü! Kesinlikle!'::text),
(318150,35350,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap ... a világ legnehezebb feladatát! Abszolút!'::text,'megoldotta'::text,'megoldja'::text,'megoldani'::text,'Tegnap megoldotta a világ legnehezebb feladatát! Abszolút!'::text),
(318153,35351,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er löst jeden Tag Aufgaben, und gestern ... er eine schwere.'::text,'löste'::text,'löst'::text,NULL::text,'Er löst jeden Tag Aufgaben, und gestern löste er eine schwere.'::text),
(318157,35351,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він щодня розв''язує задачі, а вчора ... одну складну.'::text,'розв''язав'::text,'розв''язує'::text,NULL::text,'Він щодня розв''язує задачі, а вчора розв''язав одну складну.'::text),
(318156,35351,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Resuelve problemas a diario, y ayer ... uno difícil.'::text,'resolvió'::text,'resuelve'::text,NULL::text,'Resuelve problemas a diario, y ayer resolvió uno difícil.'::text),
(318155,35351,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il résout des problèmes tous les jours, et hier il en ... un difficile.'::text,'a résolu'::text,'résout'::text,NULL::text,'Il résout des problèmes tous les jours, et hier il en a résolu un difficile.'::text),
(318158,35351,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her gün problem çözer, dün de zor bir tane ...'::text,'çözdü'::text,'çözer'::text,NULL::text,'Her gün problem çözer, dün de zor bir tane çözdü.'::text),
(318159,35351,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Naponta old meg feladatokat, és tegnap egy nehezet ...'::text,'oldott meg'::text,'old meg'::text,NULL::text,'Naponta old meg feladatokat, és tegnap egy nehezet oldott meg.'::text),
(318162,35352,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... er eine lange Matheaufgabe an der Tafel.'::text,'löst'::text,'löst'::text,'löst'::text,'Gerade löst er eine lange Matheaufgabe an der Tafel.'::text),
(318166,35352,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз він ... довгу задачу з математики на дошці.'::text,'розв''язує'::text,'розв''язує'::text,'розв''язує'::text,'Саме зараз він розв''язує довгу задачу з математики на дошці.'::text),
(318165,35352,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... un problema de mates largo en la pizarra.'::text,'está resolviendo'::text,'resuelve'::text,'está resolviendo'::text,'Ahora mismo está resolviendo un problema de mates largo en la pizarra.'::text),
(318164,35352,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, il ... un long problème de maths au tableau.'::text,'est en train de résoudre'::text,'résout'::text,'est en train de résoudre'::text,'En ce moment, il est en train de résoudre un long problème de maths au tableau.'::text),
(318167,35352,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an tahtada uzun bir matematik problemi ...'::text,'çözüyor'::text,'çözer'::text,'çözüyor'::text,'Şu an tahtada uzun bir matematik problemi çözüyor.'::text),
(318168,35352,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most egy hosszú matekfeladatot ... a táblán.'::text,'old meg'::text,'old meg'::text,'old meg'::text,'Épp most egy hosszú matekfeladatot old meg a táblán.'::text),
(318180,35354,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chill, Alter, er ... das in fünf Minuten lösen, ehrlich.'::text,'wird'::text,'ist'::text,'wird'::text,'Chill, Alter, er wird das in fünf Minuten lösen, ehrlich.'::text),
(318184,35354,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розслабся, бро, він ... її за п''ять хвилин, чесно.'::text,'розв''яже'::text,'є'::text,'збирається розв''язати'::text,'Розслабся, бро, він розв''яже її за п''ять хвилин, чесно.'::text),
(318183,35354,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tranqui, tío, ... resolverlo en cinco minutos, te lo juro.'::text,''::text,'está'::text,'va a'::text,'Tranqui, tío, resolverlo en cinco minutos, te lo juro.'::text),
(318182,35354,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chill, frérot, il ... le résoudre en cinq minutes, sans mentir.'::text,''::text,'est'::text,'va'::text,'Chill, frérot, il le résoudre en cinq minutes, sans mentir.'::text),
(318185,35354,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahat ol kanka, beş dakikada ..., cidden.'::text,'çözecek'::text,NULL::text,'çözecek'::text,'Rahat ol kanka, beş dakikada çözecek, cidden.'::text),
(318186,35354,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chill, tesó, öt perc alatt meg ... oldani, komolyan.'::text,'fogja'::text,'van'::text,'fogja'::text,'Chill, tesó, öt perc alatt meg fogja oldani, komolyan.'::text),
(318189,35355,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap: Er ... vor dem Mittagessen 12 Gleichungen lösen.'::text,'wird'::text,'wird'::text,'ist'::text,'Roadmap: Er wird vor dem Mittagessen 12 Gleichungen lösen.'::text),
(318193,35355,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дорожня карта: він ... розв''язати 12 рівнянь до обіду.'::text,'збирається'::text,'буде'::text,'є'::text,'Дорожня карта: він збирається розв''язати 12 рівнянь до обіду.'::text),
(318192,35355,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hoja de ruta: ... resolver 12 ecuaciones antes de comer.'::text,'va a'::text,NULL::text,'está'::text,'Hoja de ruta: va a resolver 12 ecuaciones antes de comer.'::text),
(318191,35355,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Roadmap : il ... résoudre 12 équations avant le déjeuner.'::text,'va'::text,NULL::text,'est'::text,'Roadmap : il va résoudre 12 équations avant le déjeuner.'::text),
(318194,35355,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yol haritası: öğle yemeğinden önce 12 denklem ...'::text,'çözecek'::text,'çözecek'::text,NULL::text,'Yol haritası: öğle yemeğinden önce 12 denklem çözecek.'::text),
(318195,35355,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ütemterv: ebéd előtt 12 egyenletet ... megoldani.'::text,'fog'::text,'fog'::text,'van'::text,'Ütemterv: ebéd előtt 12 egyenletet fog megoldani.'::text),
(318198,35356,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er hat Kreide, also ... er es lösen. Kreide ist für Mathe.'::text,'wird'::text,'wird'::text,NULL::text,'Er hat Kreide, also wird er es lösen. Kreide ist für Mathe.'::text),
(318202,35356,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У нього є крейда, тож він ... її розв''язати. Крейда — для математики.'::text,'збирається'::text,'буде'::text,NULL::text,'У нього є крейда, тож він збирається її розв''язати. Крейда — для математики.'::text),
(318201,35356,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tiene tiza, así que ... resolverlo. La tiza es para las mates.'::text,'va a'::text,NULL::text,NULL::text,'Tiene tiza, así que va a resolverlo. La tiza es para las mates.'::text),
(318200,35356,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a de la craie, donc il ... le résoudre. La craie, c''est pour les maths.'::text,'va'::text,NULL::text,NULL::text,'Il a de la craie, donc il va le résoudre. La craie, c''est pour les maths.'::text),
(318203,35356,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tebeşiri var, bu yüzden onu ... – tebeşir matematik içindir.'::text,'çözecek'::text,'çözecek'::text,NULL::text,'Tebeşiri var, bu yüzden onu çözecek – tebeşir matematik içindir.'::text),
(318204,35356,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Van krétája, ezért meg ... oldani. A kréta a matekhoz való.'::text,'fogja'::text,'fogja'::text,NULL::text,'Van krétája, ezért meg fogja oldani. A kréta a matekhoz való.'::text),
(312393,34711,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er tippt sich an den Kopf, und jetzt ... er sich an das Wort erinnern.'::text,'kann'::text,'ist'::text,'kann'::text,'Er tippt sich an den Kopf, und jetzt kann er sich an das Wort erinnern.'::text),
(312397,34711,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він стукає себе по голові, і тепер ... згадати слово.'::text,'може'::text,'є'::text,'може'::text,'Він стукає себе по голові, і тепер може згадати слово.'::text),
(312396,34711,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se da golpecitos en la cabeza y ahora ... recordar la palabra.'::text,'puede'::text,'está'::text,'puede'::text,'Se da golpecitos en la cabeza y ahora puede recordar la palabra.'::text),
(312395,34711,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il se tapote la tête, et maintenant il ... se souvenir du mot.'::text,'peut'::text,'est'::text,'peut'::text,'Il se tapote la tête, et maintenant il peut se souvenir du mot.'::text),
(312398,34711,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Başına vuruyor ve artık kelimeyi ...'::text,'hatırlayabilir'::text,NULL::text,'hatırlayabilir'::text,'Başına vuruyor ve artık kelimeyi hatırlayabilir.'::text),
(312399,34711,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megkocogtatja a fejét, és most már fel ... idézni a szót.'::text,'tudja'::text,'van'::text,'tudja'::text,'Megkocogtatja a fejét, és most már fel tudja idézni a szót.'::text),
(312402,34712,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... merkt er sich die Wörter? Mit kleinen Karten.'::text,'Wie'::text,'Wer'::text,'Wo'::text,'Wie merkt er sich die Wörter? Mit kleinen Karten.'::text),
(312406,34712,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... він запам''ятовує слова? За допомогою маленьких карток.'::text,'Як'::text,'Хто'::text,'Де'::text,'Як він запам''ятовує слова? За допомогою маленьких карток.'::text),
(312405,34712,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... recuerda las palabras? Con tarjetas pequeñas.'::text,'Cómo'::text,'Quién'::text,'Dónde'::text,'¿Cómo recuerda las palabras? Con tarjetas pequeñas.'::text),
(312404,34712,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... retient-il les mots ? Avec de petites cartes.'::text,'Comment'::text,'Qui'::text,'Où'::text,'Comment retient-il les mots ? Avec de petites cartes.'::text),
(312407,34712,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kelimeleri ... hatırlıyor? Küçük kartlarla.'::text,'nasıl'::text,'kim'::text,'nerede'::text,'Kelimeleri nasıl hatırlıyor? Küçük kartlarla.'::text),
(312408,34712,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... jegyzi meg a szavakat? Kis kártyákkal.'::text,'Hogyan'::text,'Ki'::text,'Hol'::text,'Hogyan jegyzi meg a szavakat? Kis kártyákkal.'::text),
(312411,34713,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, er ... sich gestern Abend alle fünfzig Karten, ehrlich.'::text,'merkte'::text,'merkt'::text,'merken'::text,'Alter, er merkte sich gestern Abend alle fünfzig Karten, ehrlich.'::text),
(312415,34713,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він учора ввечері ... всі п''ятдесят карток, чесно.'::text,'запам''ятав'::text,'запам''ятовує'::text,'запам''ятати'::text,'Бро, він учора ввечері запам''ятав всі п''ятдесят карток, чесно.'::text),
(312414,34713,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, anoche ... las cincuenta tarjetas, te lo juro.'::text,'memorizó'::text,'memoriza'::text,'memorizar'::text,'Tío, anoche memorizó las cincuenta tarjetas, te lo juro.'::text),
(312413,34713,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, hier soir il ... les cinquante cartes, sans mentir.'::text,'a retenu'::text,'retient'::text,'retenir'::text,'Frérot, hier soir il a retenu les cinquante cartes, sans mentir.'::text),
(312416,34713,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dün gece elli kartın hepsini ..., cidden.'::text,'ezberledi'::text,'ezberler'::text,'ezberlemek'::text,'Kanka, dün gece elli kartın hepsini ezberledi, cidden.'::text),
(312417,34713,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, tegnap este mind az ötven kártyát ..., komolyan.'::text,'megjegyezte'::text,'megjegyzi'::text,'megjegyezni'::text,'Tesó, tegnap este mind az ötven kártyát megjegyezte, komolyan.'::text),
(312429,34715,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Prüfung ist morgen, also ... er sich die Wörter merken. Prüfungen haben Wörter.'::text,'muss'::text,'muss'::text,'sollte'::text,'Die Prüfung ist morgen, also muss er sich die Wörter merken. Prüfungen haben Wörter.'::text),
(312433,34715,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Іспит завтра, тож він ... запам''ятати слова. В іспитах є слова.'::text,'має'::text,'мусить'::text,'мав би'::text,'Іспит завтра, тож він має запам''ятати слова. В іспитах є слова.'::text),
