(312438,34716,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um dir all die Karten zu merken, ... du ein bisschen schlafen, ehrlich.'::text,'solltest'::text,'solltest'::text,'solltest'::text,'Um dir all die Karten zu merken, solltest du ein bisschen schlafen, ehrlich.'::text),
