(312443,34716,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütün o kartları hatırlamak için biraz ..., cidden.'::text,'uyumalısın'::text,'uyumalısın'::text,'uyumalısın'::text,'Bütün o kartları hatırlamak için biraz uyumalısın, cidden.'::text),
