(309560,34396,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... pièces y a-t-il sur la table ?'::text,'Combien de'::text,'Combien de'::text,'Des'::text,'Combien de pièces y a-t-il sur la table ?'::text),
(309563,34396,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Masada ... parça var?'::text,'kaç'::text,'ne kadar'::text,'biraz'::text,'Masada kaç parça var?'::text),
(309564,34396,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... darab van az asztalon?'::text,'Hány'::text,'Mennyi'::text,'Néhány'::text,'Hány darab van az asztalon?'::text),
(309567,34397,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Da ... Hunderte Teile, und du findest jedes einzelne? Beeindruckt.'::text,'sind'::text,'ist'::text,'sein'::text,'Da sind Hunderte Teile, und du findest jedes einzelne? Beeindruckt.'::text),
(309571,34397,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тут ... сотні деталей, і ти знаходиш кожну? Я вражена.'::text,'є'::text,'є'::text,'бути'::text,'Тут є сотні деталей, і ти знаходиш кожну? Я вражена.'::text),
(309570,34397,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cientos de piezas, ¿y las encuentras todas? Me dejas impresionada.'::text,'Hay'::text,'Hay'::text,'Hay'::text,'Hay cientos de piezas, ¿y las encuentras todas? Me dejas impresionada.'::text),
(309569,34397,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des centaines de pièces, et tu les trouves toutes ? Impressionnée.'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Il y a des centaines de pièces, et tu les trouves toutes ? Impressionnée.'::text),
(309572,34397,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzlerce parça ... ve sen her birini buluyor musun? Etkilendim.'::text,'var'::text,'var'::text,'olmak'::text,'Yüzlerce parça var ve sen her birini buluyor musun? Etkilendim.'::text),
(309573,34397,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Több száz darab ..., és te mindet megtalálod? Le vagyok nyűgözve.'::text,'van'::text,'vannak'::text,'lenni'::text,'Több száz darab van, és te mindet megtalálod? Le vagyok nyűgözve.'::text),
(303735,33749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... stundenlang dem Wasserfall zu! Ihre Ohren sind völlig kaputt!'::text,'hörte'::text,'hören'::text,'hörte'::text,'Sie hörte stundenlang dem Wasserfall zu! Ihre Ohren sind völlig kaputt!'::text),
(303739,33749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... водоспад годинами! Її вуха повністю зруйновані!'::text,'слухала'::text,'слухати'::text,'слухала'::text,'Вона слухала водоспад годинами! Її вуха повністю зруйновані!'::text),
(303738,33749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... la cascada durante horas! ¡Tiene los oídos completamente destrozados!'::text,'Escuchó'::text,'Escuchar'::text,'Escuchó'::text,'¡Escuchó la cascada durante horas! ¡Tiene los oídos completamente destrozados!'::text),
(303737,33749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... la cascade pendant des heures ! Ses oreilles sont complètement détruites !'::text,'a écouté'::text,'écouter'::text,'a écouté'::text,'Elle a écouté la cascade pendant des heures ! Ses oreilles sont complètement détruites !'::text),
(303740,33749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şelaleyi saatlerce ...! Kulakları tamamen mahvoldu!'::text,'dinledi'::text,'dinlemek'::text,'dinledi'::text,'Şelaleyi saatlerce dinledi! Kulakları tamamen mahvoldu!'::text),
(303741,33749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Órákig ... a vízesést! A füle teljesen tönkrement!'::text,'hallgatta'::text,'hallgatni'::text,'hallgatta'::text,'Órákig hallgatta a vízesést! A füle teljesen tönkrement!'::text),
(303744,33750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Moment, anscheinend hört sie jeden Tag Vögeln zu, aber gestern ... sie einem Bach zu.'::text,'hörte'::text,'hört'::text,NULL::text,'Moment, anscheinend hört sie jeden Tag Vögeln zu, aber gestern hörte sie einem Bach zu.'::text),
(303748,33750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стривай, вона нібито щодня слухає птахів, а вчора ... струмок.'::text,'слухала'::text,'слухає'::text,NULL::text,'Стривай, вона нібито щодня слухає птахів, а вчора слухала струмок.'::text),
(303747,33750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Espera, al parecer escucha pájaros a diario, pero ayer ... un arroyo.'::text,'escuchó'::text,'escucha'::text,NULL::text,'Espera, al parecer escucha pájaros a diario, pero ayer escuchó un arroyo.'::text),
(303746,33750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Attends, apparemment elle écoute les oiseaux tous les jours, mais hier elle ... un ruisseau.'::text,'a écouté'::text,'écoute'::text,NULL::text,'Attends, apparemment elle écoute les oiseaux tous les jours, mais hier elle a écouté un ruisseau.'::text),
(303749,33750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur, meğer her gün kuşları dinlermiş ama dün bir dereyi ...'::text,'dinledi'::text,'dinler'::text,NULL::text,'Dur, meğer her gün kuşları dinlermiş ama dün bir dereyi dinledi.'::text),
(303750,33750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Várj, állítólag naponta madarakat hallgat, de tegnap egy patakot ...'::text,'hallgatott'::text,'hallgat'::text,NULL::text,'Várj, állítólag naponta madarakat hallgat, de tegnap egy patakot hallgatott.'::text),
(303753,33751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jetzt ... sie mit ihren Kopfhörern einem Vogel zu.'::text,'hört'::text,'hört'::text,'hört'::text,'Jetzt hört sie mit ihren Kopfhörern einem Vogel zu.'::text),
(303757,33751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зараз вона ... пташку в навушниках.'::text,'слухає'::text,'слухає'::text,'слухає'::text,'Зараз вона слухає пташку в навушниках.'::text),
(303756,33751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora ... a un pájaro con sus cascos.'::text,'está escuchando'::text,'escucha'::text,'está escuchando'::text,'Ahora está escuchando a un pájaro con sus cascos.'::text),
(303755,33751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maintenant, elle ... un oiseau avec son casque.'::text,'est en train d''écouter'::text,'écoute'::text,'est en train d''écouter'::text,'Maintenant, elle est en train d''écouter un oiseau avec son casque.'::text),
(303758,33751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şimdi kulaklığıyla bir kuşu ...'::text,'dinliyor'::text,'dinler'::text,'dinliyor'::text,'Şimdi kulaklığıyla bir kuşu dinliyor.'::text),
(303759,33751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Most egy madarat ... a fejhallgatójával.'::text,'hallgat'::text,'hallgat'::text,'hallgat'::text,'Most egy madarat hallgat a fejhallgatójával.'::text),
(303771,33753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, der Wasserfall ist leise, also ... sie ihm den ganzen Tag zuhören.'::text,'wird'::text,'ist'::text,NULL::text,'Klar, der Wasserfall ist leise, also wird sie ihm den ganzen Tag zuhören.'::text),
(303775,33753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звісно, водоспад тихий, тож вона ... слухати його весь день.'::text,'буде'::text,'є'::text,NULL::text,'Звісно, водоспад тихий, тож вона буде слухати його весь день.'::text),
(303774,33753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Obviamente, la cascada es silenciosa, así que ... escucharla todo el día.'::text,''::text,'está'::text,NULL::text,'Obviamente, la cascada es silenciosa, así que escucharla todo el día.'::text),
(303773,33753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, la cascade est calme, donc elle ... l''écouter toute la journée.'::text,''::text,'est'::text,NULL::text,'Évidemment, la cascade est calme, donc elle l''écouter toute la journée.'::text),
(303776,33753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabii ki şelale sessiz, bu yüzden onu bütün gün ...'::text,'dinleyecek'::text,NULL::text,NULL::text,'Tabii ki şelale sessiz, bu yüzden onu bütün gün dinleyecek.'::text),
(303777,33753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván csendes a vízesés, ezért egész nap ... hallgatni.'::text,'fogja'::text,'van'::text,NULL::text,'Nyilván csendes a vízesés, ezért egész nap fogja hallgatni.'::text),
(303780,33754,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein entspannter Plan, eindeutig: Sie ... einem donnernden Wasserfall zuhören.'::text,'wird'::text,'werden'::text,'wird'::text,'Ein entspannter Plan, eindeutig: Sie wird einem donnernden Wasserfall zuhören.'::text),
(303784,33754,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Розслаблений план, явно: вона ... слухати гуркітливий водоспад.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Розслаблений план, явно: вона збирається слухати гуркітливий водоспад.'::text),
(303783,33754,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un plan relajante, está claro: ... escuchar una cascada atronadora.'::text,'va a'::text,'van a'::text,'va a'::text,'Un plan relajante, está claro: va a escuchar una cascada atronadora.'::text),
(303782,33754,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un plan relaxant, clairement : elle ... écouter une cascade assourdissante.'::text,'va'::text,'vont'::text,'va'::text,'Un plan relaxant, clairement : elle va écouter une cascade assourdissante.'::text),
(303785,33754,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rahatlatıcı bir plan, belli: gürleyen bir şelaleyi ...'::text,'dinleyecek'::text,'dinleyecekler'::text,'dinleyecek'::text,'Rahatlatıcı bir plan, belli: gürleyen bir şelaleyi dinleyecek.'::text),
(303786,33754,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pihentető terv, egyértelműen: egy dübörgő vízesést ... hallgatni.'::text,'fog'::text,'fognak'::text,'fog'::text,'Pihentető terv, egyértelműen: egy dübörgő vízesést fog hallgatni.'::text),
(303789,33755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super, ein Wasserfall direkt neben meinem Vogel. Na gut, ich ... genauer hinhören.'::text,'werde'::text,'werde'::text,NULL::text,'Super, ein Wasserfall direkt neben meinem Vogel. Na gut, ich werde genauer hinhören.'::text),
(303793,33755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудово, водоспад поруч із моєю пташкою. Гаразд, я ... слухати уважніше.'::text,'буду'::text,'збираюся'::text,NULL::text,'Чудово, водоспад поруч із моєю пташкою. Гаразд, я буду слухати уважніше.'::text),
(303792,33755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genial, una cascada al lado de mi pájaro. Vale, ... escuchar con más atención.'::text,''::text,'voy a'::text,NULL::text,'Genial, una cascada al lado de mi pájaro. Vale, escuchar con más atención.'::text),
(303791,33755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Génial, une cascade juste à côté de mon oiseau. Bon, je ... écouter plus attentivement.'::text,''::text,'vais'::text,NULL::text,'Génial, une cascade juste à côté de mon oiseau. Bon, je écouter plus attentivement.'::text),
(303794,33755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika, kuşumun hemen yanında bir şelale. Peki, daha dikkatli ...'::text,'dinleyeceğim'::text,'dinleyeceğim'::text,NULL::text,'Harika, kuşumun hemen yanında bir şelale. Peki, daha dikkatli dinleyeceğim.'::text),
(303795,33755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szuper, egy vízesés a madaram mellett. Jó, figyelmesebben ... hallgatni.'::text,'fogok'::text,'fogok'::text,NULL::text,'Szuper, egy vízesés a madaram mellett. Jó, figyelmesebben fogok hallgatni.'::text),
(309855,34429,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie schreibt ... Plan in einen Planer.'::text,'ihren'::text,'seinen'::text,'seinen'::text,'Sie schreibt ihren Plan in einen Planer.'::text),
(309859,34429,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона записує ... план у планер.'::text,'свій'::text,'свій'::text,'свій'::text,'Вона записує свій план у планер.'::text),
(309858,34429,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escribe ... plan en una agenda.'::text,'su'::text,'su'::text,'su'::text,'Escribe su plan en una agenda.'::text),
(309857,34429,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle écrit ... plan dans un agenda.'::text,'son'::text,'son'::text,'son'::text,'Elle écrit son plan dans un agenda.'::text),
(309860,34429,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... planını bir ajandaya yazıyor.'::text,'Onun'::text,'Onun'::text,'Onun'::text,'Onun planını bir ajandaya yazıyor.'::text),
(309861,34429,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beírja a ... egy határidőnaplóba.'::text,'tervét'::text,'tervét'::text,'tervét'::text,'Beírja a tervét egy határidőnaplóba.'::text),
(309864,34430,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die erste Notiz in ihrem Plan ist ... Montag.'::text,'am'::text,'im'::text,'um'::text,'Die erste Notiz in ihrem Plan ist am Montag.'::text),
(309868,34430,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перша нотатка в її плані — ... понеділок.'::text,'на'::text,'у'::text,'о'::text,'Перша нотатка в її плані — на понеділок.'::text),
(309867,34430,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La primera nota de su plan es ... el lunes.'::text,''::text,'en'::text,'a'::text,'La primera nota de su plan es el lunes.'::text),
(309866,34430,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La première note de son plan est ... lundi.'::text,''::text,'dans'::text,'à'::text,'La première note de son plan est lundi.'::text),
(309869,34430,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planındaki ilk not pazartesi ...'::text,''::text,NULL::text,NULL::text,'Planındaki ilk not pazartesi.'::text),
(309870,34430,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A terve első jegyzete ... van.'::text,'hétfőn'::text,'hétfőben'::text,'hétfőkor'::text,'A terve első jegyzete hétfőn van.'::text),
(309873,34431,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Plan hat mehr als ... Notizen.'::text,'hundert'::text,'Hunderte'::text,'hundertste'::text,'Ihr Plan hat mehr als hundert Notizen.'::text),
(309877,34431,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У її плані більше ніж ... нотаток.'::text,'сто'::text,'сотні'::text,'сота'::text,'У її плані більше ніж сто нотаток.'::text),
(309876,34431,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su plan tiene más de ... notas.'::text,'cien'::text,'cientos'::text,'centésima'::text,'Su plan tiene más de cien notas.'::text),
(309875,34431,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son plan a plus de ... notes.'::text,'cent'::text,'centaines'::text,'centième'::text,'Son plan a plus de cent notes.'::text),
(309878,34431,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planında ... notadan fazlası var.'::text,'yüz'::text,'yüzler'::text,'yüzüncü'::text,'Planında yüz notadan fazlası var.'::text),
(309879,34431,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tervében több mint ... jegyzet van.'::text,'száz'::text,'százak'::text,'századik'::text,'A tervében több mint száz jegyzet van.'::text),
(309891,34433,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Es ist nicht ... Platz für den Plan an der Wand!'::text,'viel'::text,'viele'::text,'etwas'::text,'Katastrophe! Es ist nicht viel Platz für den Plan an der Wand!'::text),
(309895,34433,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! На стіні не так ... місця для плану!'::text,'багато'::text,'багато'::text,'трохи'::text,'Катастрофа! На стіні не так багато місця для плану!'::text),
(309894,34433,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡No hay ... espacio para el plan en la pared!'::text,'mucho'::text,'muchos'::text,'algo de'::text,'¡Desastre! ¡No hay mucho espacio para el plan en la pared!'::text),
(309893,34433,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Il n''y a pas ... place pour le plan sur le mur !'::text,'beaucoup de'::text,'beaucoup de'::text,'de la'::text,'Catastrophe ! Il n''y a pas beaucoup de place pour le plan sur le mur !'::text),
(309896,34433,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Duvarda plan için ... yer yok!'::text,'çok'::text,'çok'::text,'biraz'::text,'Felaket! Duvarda plan için çok yer yok!'::text),
(309897,34433,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Nincs ... hely a tervnek a falon!'::text,'sok'::text,'sok'::text,'némi'::text,'Katasztrófa! Nincs sok hely a tervnek a falon!'::text),
(309900,34434,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, ich hab gehört, in ihrem Plan ... dreihundert Notizen.'::text,'sind'::text,'ist'::text,'sein'::text,'Mädel, ich hab gehört, in ihrem Plan sind dreihundert Notizen.'::text),
(309904,34434,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, я чула, що в її плані ... триста нотаток.'::text,'є'::text,'є'::text,'бути'::text,'Подруго, я чула, що в її плані є триста нотаток.'::text),
(309903,34434,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me han dicho que ... trescientas notas en su plan.'::text,'hay'::text,'hay'::text,'hay'::text,'Tía, me han dicho que hay trescientas notas en su plan.'::text),
(309902,34434,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, on m''a dit que dans son plan ... trois cents notes.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Ma belle, on m''a dit que dans son plan il y a trois cents notes.'::text),
(309905,34434,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duydum ki planında üç yüz not ...'::text,'var'::text,'var'::text,'olmak'::text,'Kızım, duydum ki planında üç yüz not var.'::text),
(309906,34434,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt hallottam, hogy háromszáz jegyzet ... a tervében.'::text,'van'::text,'van'::text,'lenni'::text,'Csajszi, azt hallottam, hogy háromszáz jegyzet van a tervében.'::text),
(309909,34435,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, ihr Chef hat mir gesagt, dass sie den Plan bis Freitag fertig machen ...'::text,'muss'::text,'muss'::text,'sollte'::text,'Hör zu, ihr Chef hat mir gesagt, dass sie den Plan bis Freitag fertig machen muss.'::text),
(309913,34435,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, її шеф сказав мені, що вона ... закінчити план до п''ятниці.'::text,'має'::text,'мусить'::text,'мала б'::text,'Слухай, її шеф сказав мені, що вона має закінчити план до п''ятниці.'::text),
(309912,34435,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, su jefe me dijo que ... terminar el plan antes del viernes.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Oye, su jefe me dijo que tiene que terminar el plan antes del viernes.'::text),
(309911,34435,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, son boss m''a dit qu''elle ... finir le plan d''ici vendredi.'::text,'doit'::text,'doit'::text,'devrait'::text,'Écoute, son boss m''a dit qu''elle doit finir le plan d''ici vendredi.'::text),
(309914,34435,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, patronu bana planı cumaya kadar ... söyledi.'::text,'bitirmek zorunda olduğunu'::text,'bitirmesi gerektiğini'::text,'bitirmesi gerektiğini'::text,'Dinle, patronu bana planı cumaya kadar bitirmek zorunda olduğunu söyledi.'::text),
(309915,34435,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, a főnöke azt mondta, hogy péntekig be ... fejeznie a tervet.'::text,'kell'::text,'kell'::text,'kellene'::text,'Figyelj, a főnöke azt mondta, hogy péntekig be kell fejeznie a tervet.'::text),
(325299,36145,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eine Band in Uniformen ... in ihr Büro.'::text,'marschiert'::text,'marschiert'::text,'marschiert'::text,'Eine Band in Uniformen marschiert in ihr Büro.'::text),
(325303,36145,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Оркестр в уніформі ... до її офісу.'::text,'марширує'::text,'марширує'::text,'марширує'::text,'Оркестр в уніформі марширує до її офісу.'::text),
(325302,36145,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una banda de uniforme ... hacia su despacho.'::text,'está desfilando'::text,'desfila'::text,'está desfilando'::text,'Una banda de uniforme está desfilando hacia su despacho.'::text),
(325301,36145,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une fanfare en uniforme ... dans son bureau.'::text,'est en train de défiler'::text,'défile'::text,'est en train de défiler'::text,'Une fanfare en uniforme est en train de défiler dans son bureau.'::text),
(325304,36145,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üniformalı bir bando onun ofisine ...'::text,'yürüyor'::text,'yürür'::text,'yürüyor'::text,'Üniformalı bir bando onun ofisine yürüyor.'::text),
(325305,36145,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy egyenruhás zenekar ... be az irodájába.'::text,'masírozik'::text,'masírozik'::text,'masírozik'::text,'Egy egyenruhás zenekar masírozik be az irodájába.'::text),
(325317,36147,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... den Anruf beenden, sogar mit einer Band in Uniformen. Respekt.'::text,'wirst'::text,'beendest'::text,'beendetest'::text,'Du wirst den Anruf beenden, sogar mit einer Band in Uniformen. Respekt.'::text),
(325321,36147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... цей дзвінок, навіть з оркестром в уніформі. Респект.'::text,'завершиш'::text,'завершуєш'::text,'завершила'::text,'Ти завершиш цей дзвінок, навіть з оркестром в уніформі. Респект.'::text),
(325320,36147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... esa llamada, incluso con una banda de uniforme. Respeto.'::text,'Terminarás'::text,'Terminas'::text,'Terminaste'::text,'Terminarás esa llamada, incluso con una banda de uniforme. Respeto.'::text),
(325319,36147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... cet appel, même avec une fanfare en uniforme. Respect.'::text,'finiras'::text,'finis'::text,'as fini'::text,'Tu finiras cet appel, même avec une fanfare en uniforme. Respect.'::text),
(325322,36147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üniformalı bir bando olsa bile o görüşmeyi ... – saygılar.'::text,'bitireceksin'::text,'bitirirsin'::text,'bitirdin'::text,'Üniformalı bir bando olsa bile o görüşmeyi bitireceksin – saygılar.'::text),
(325323,36147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... azt a hívást, még egy egyenruhás zenekarral is. Respekt.'::text,'Be fogod fejezni'::text,'Befejezed'::text,'Befejezted'::text,'Be fogod fejezni azt a hívást, még egy egyenruhás zenekarral is. Respekt.'::text),
(325326,36148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du hast einen Plan: Du ... die Band in Uniformen rauswerfen.'::text,'wirst'::text,'wirst'::text,'wirst'::text,'Ehrlich, du hast einen Plan: Du wirst die Band in Uniformen rauswerfen.'::text),
(325330,36148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, у тебе є план: ти ... вигнати оркестр в уніформі.'::text,'збираєшся'::text,'будеш'::text,'збираєшся'::text,'Чесно, у тебе є план: ти збираєшся вигнати оркестр в уніформі.'::text),
(325329,36148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, tienes un plan: ... echar a la banda de uniforme.'::text,'vas a'::text,NULL::text,'vas a'::text,'En serio, tienes un plan: vas a echar a la banda de uniforme.'::text),
(325328,36148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu as un plan : tu ... virer la fanfare en uniforme.'::text,'vas'::text,NULL::text,'vas'::text,'Franchement, tu as un plan : tu vas virer la fanfare en uniforme.'::text),
(325331,36148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası bir planın var: üniformalı bandoyu ...'::text,'kovacaksın'::text,'kovacaksın'::text,'kovacaksın'::text,'Açıkçası bir planın var: üniformalı bandoyu kovacaksın.'::text),
(325332,36148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, van egy terved: ki ... dobni az egyenruhás zenekart.'::text,'fogod'::text,'fogod'::text,'fogod'::text,'Őszintén, van egy terved: ki fogod dobni az egyenruhás zenekart.'::text),
(325335,36149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super Timing, klar: Eine Band in Uniformen marschiert herein. Ihr Anruf ... scheitern.'::text,'wird'::text,'wird'::text,NULL::text,'Super Timing, klar: Eine Band in Uniformen marschiert herein. Ihr Anruf wird scheitern.'::text),
(325339,36149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий таймінг, звісно: заходить оркестр в уніформі. Її дзвінок ... провалитися.'::text,'збирається'::text,'буде'::text,NULL::text,'Чудовий таймінг, звісно: заходить оркестр в уніформі. Її дзвінок збирається провалитися.'::text),
(325338,36149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué oportuno, claro: entra desfilando una banda de uniforme. Su llamada ... fracasar.'::text,'va a'::text,NULL::text,NULL::text,'Qué oportuno, claro: entra desfilando una banda de uniforme. Su llamada va a fracasar.'::text),
(325337,36149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Timing parfait, évidemment : une fanfare en uniforme entre au pas. Son appel ... échouer.'::text,'va'::text,NULL::text,NULL::text,'Timing parfait, évidemment : une fanfare en uniforme entre au pas. Son appel va échouer.'::text),
(325340,36149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika zamanlama, belli: üniformalı bir bando içeri giriyor. Görüşmesi ...'::text,'mahvolacak'::text,'mahvolacak'::text,NULL::text,'Harika zamanlama, belli: üniformalı bir bando içeri giriyor. Görüşmesi mahvolacak.'::text),
(325341,36149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Remek időzítés, persze: bemasírozik egy egyenruhás zenekar. A hívása el ... bukni.'::text,'fog'::text,'fog'::text,NULL::text,'Remek időzítés, persze: bemasírozik egy egyenruhás zenekar. A hívása el fog bukni.'::text),
(325344,36150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein perfekter Arbeitsanruf, klar: überall Uniformen und so viel ... um sie herum.'::text,'Lärm'::text,'Lärm'::text,'ein Lärm'::text,'Ein perfekter Arbeitsanruf, klar: überall Uniformen und so viel Lärm um sie herum.'::text),
(325348,36150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ідеальний робочий дзвінок, звісно: скрізь уніформи й стільки ... довкола неї.'::text,'шуму'::text,'шумів'::text,'шуму'::text,'Ідеальний робочий дзвінок, звісно: скрізь уніформи й стільки шуму довкола неї.'::text),
(325347,36150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una llamada de trabajo perfecta, claro: uniformes por todas partes y tanto ... a su alrededor.'::text,'ruido'::text,'ruido'::text,'un ruido'::text,'Una llamada de trabajo perfecta, claro: uniformes por todas partes y tanto ruido a su alrededor.'::text),
(325346,36150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un appel pro parfait, évidemment : des uniformes partout et tellement de ... autour d''elle.'::text,'bruit'::text,'bruit'::text,'un bruit'::text,'Un appel pro parfait, évidemment : des uniformes partout et tellement de bruit autour d''elle.'::text),
(325349,36150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mükemmel bir iş görüşmesi, belli: her yerde üniformalar ve etrafında o kadar çok ... var.'::text,'gürültü'::text,'gürültüler'::text,'bir gürültü'::text,'Mükemmel bir iş görüşmesi, belli: her yerde üniformalar ve etrafında o kadar çok gürültü var.'::text),
(325350,36150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tökéletes munkahívás, persze: mindenhol egyenruhák, és annyi ... körülötte.'::text,'zaj'::text,'zaj'::text,'egy zaj'::text,'Tökéletes munkahívás, persze: mindenhol egyenruhák, és annyi zaj körülötte.'::text),
(325353,36151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, wie ... Uniformen passen in ein Büro, echt jetzt?'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Alter, wie viele Uniformen passen in ein Büro, echt jetzt?'::text),
(325357,36151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... уніформ влізе в один офіс, серйозно?'::text,'скільки'::text,'скільки'::text,'будь-яких'::text,'Бро, скільки уніформ влізе в один офіс, серйозно?'::text),
(325356,36151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... uniformes caben en una oficina, en serio?'::text,'cuántos'::text,'cuánto'::text,'cualquier'::text,'Tío, ¿cuántos uniformes caben en una oficina, en serio?'::text),
(325355,36151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ... uniformes peuvent tenir dans un seul bureau, sérieux ?'::text,'combien d'''::text,'combien d'''::text,'n''importe quels'::text,'Frérot, combien d'' uniformes peuvent tenir dans un seul bureau, sérieux ?'::text),
(325358,36151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, tek bir ofise ... üniforma sığar, cidden?'::text,'kaç'::text,'ne kadar'::text,'herhangi bir'::text,'Kanka, tek bir ofise kaç üniforma sığar, cidden?'::text),
(325359,36151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... egyenruha fér el egy irodában, komolyan?'::text,'hány'::text,'mennyi'::text,'bármilyen'::text,'Tesó, hány egyenruha fér el egy irodában, komolyan?'::text),
(325362,36152,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, da ... zehn Typen in Uniformen in ihrem Büro, Bruder.'::text,'sind'::text,'ist'::text,'sein'::text,'Yo, da sind zehn Typen in Uniformen in ihrem Büro, Bruder.'::text),
(325366,36152,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, в її офісі ... десять чуваків в уніформі, бро.'::text,'є'::text,'є'::text,'бути'::text,'Йо, в її офісі є десять чуваків в уніформі, бро.'::text),
(325365,36152,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buah, ... diez tíos de uniforme en su oficina, tío.'::text,'hay'::text,'hay'::text,'hay'::text,'Buah, hay diez tíos de uniforme en su oficina, tío.'::text),
(325364,36152,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, ... dix mecs en uniforme dans son bureau, frère.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Wesh, il y a dix mecs en uniforme dans son bureau, frère.'::text),
(325367,36152,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun ofisinde üniformalı on adam ..., ya.'::text,'var'::text,'var'::text,'olmak'::text,'Kanka, onun ofisinde üniformalı on adam var, ya.'::text),
(325368,36152,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyu, tíz egyenruhás csávó ... az irodájában, tesó.'::text,'van'::text,'van'::text,'lenni'::text,'Figyu, tíz egyenruhás csávó van az irodájában, tesó.'::text),
(311637,34627,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jedes Gericht ... auf ihren Karten eine Fünf-Sterne-Bewertung.'::text,'hat'::text,'haben'::text,'hat'::text,'Jedes Gericht hat auf ihren Karten eine Fünf-Sterne-Bewertung.'::text),
(311641,34627,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кожна страва ... на її картках п''ятизіркову оцінку.'::text,'має'::text,'мати'::text,'має'::text,'Кожна страва має на її картках п''ятизіркову оцінку.'::text),
(311640,34627,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cada plato ... una valoración de cinco estrellas en sus tarjetas.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'Cada plato tiene una valoración de cinco estrellas en sus tarjetas.'::text),
(311639,34627,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Chaque plat ... une note de cinq étoiles sur ses cartes.'::text,'a'::text,'ont'::text,'a'::text,'Chaque plat a une note de cinq étoiles sur ses cartes.'::text),
(311642,34627,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Onun kartlarında her yemeğin beş yıldızlı bir puanı ...'::text,'var'::text,'var'::text,'var'::text,'Onun kartlarında her yemeğin beş yıldızlı bir puanı var.'::text),
(311643,34627,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kártyáin minden ételnek ... ötcsillagos értékelése.'::text,'van'::text,'van'::text,'van'::text,'A kártyáin minden ételnek van ötcsillagos értékelése.'::text),
(311646,34628,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... jeder Schüssel Essen eine Fünf-Sterne-Bewertung.'::text,'gibt'::text,'geben'::text,'gebend'::text,'Sie gibt jeder Schüssel Essen eine Fünf-Sterne-Bewertung.'::text),
(311650,34628,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... кожній мисці з їжею п''ятизіркову оцінку.'::text,'дає'::text,'давати'::text,'даючи'::text,'Вона дає кожній мисці з їжею п''ятизіркову оцінку.'::text),
(311649,34628,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a cada bol de comida una valoración de cinco estrellas.'::text,'Da'::text,'Dar'::text,'Dando'::text,'Da a cada bol de comida una valoración de cinco estrellas.'::text),
(311648,34628,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... à chaque bol de nourriture une note de cinq étoiles.'::text,'donne'::text,'donner'::text,'donnant'::text,'Elle donne à chaque bol de nourriture une note de cinq étoiles.'::text),
(311651,34628,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her yemek kâsesine beş yıldızlı puan ...'::text,'verir'::text,'vermek'::text,'vererek'::text,'Her yemek kâsesine beş yıldızlı puan verir.'::text),
(311652,34628,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden tál ételnek ötcsillagos értékelést ...'::text,'ad'::text,'adni'::text,'adó'::text,'Minden tál ételnek ötcsillagos értékelést ad.'::text),
(311655,34629,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du ... in einer Sekunde eine Fünf-Sterne-Bewertung geben.'::text,'kannst'::text,'bist'::text,'kannst'::text,'Ehrlich, du kannst in einer Sekunde eine Fünf-Sterne-Bewertung geben.'::text),
(311659,34629,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти ... поставити п''ятизіркову оцінку за секунду.'::text,'можеш'::text,'є'::text,'можеш'::text,'Чесно, ти можеш поставити п''ятизіркову оцінку за секунду.'::text),
(311658,34629,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En serio, ... dar una valoración de cinco estrellas en un segundo.'::text,'puedes'::text,'estás'::text,'puedes'::text,'En serio, puedes dar una valoración de cinco estrellas en un segundo.'::text),
(311657,34629,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu ... donner une note de cinq étoiles en une seconde.'::text,'peux'::text,'es'::text,'peux'::text,'Franchement, tu peux donner une note de cinq étoiles en une seconde.'::text),
(311660,34629,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir saniyede beş yıldızlı puan ...'::text,'verebilirsin'::text,NULL::text,'verebilirsin'::text,'Açıkçası, bir saniyede beş yıldızlı puan verebilirsin.'::text),
(311661,34629,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egy másodperc alatt ... adni egy ötcsillagos értékelést.'::text,'tudsz'::text,'vagy'::text,'tudsz'::text,'Őszintén, egy másodperc alatt tudsz adni egy ötcsillagos értékelést.'::text),
(311673,34631,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ohne Witz, du schreibst ... besten Bewertungen der Stadt.'::text,'die'::text,'eine'::text,'eine'::text,'Ohne Witz, du schreibst die besten Bewertungen der Stadt.'::text),
(311677,34631,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не брехатиму, ти пишеш ... найкращі відгуки в місті.'::text,''::text,NULL::text,NULL::text,'Не брехатиму, ти пишеш найкращі відгуки в місті.'::text),
(311676,34631,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, escribes ... mejores valoraciones de la ciudad.'::text,'las'::text,'una'::text,'una'::text,'No te voy a mentir, escribes las mejores valoraciones de la ciudad.'::text),
(311675,34631,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu écris ... meilleures notes de la ville.'::text,'les'::text,'une'::text,'une'::text,'Je vais pas mentir, tu écris les meilleures notes de la ville.'::text),
(311678,34631,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, şehrin ... en iyi puanlarını sen yazıyorsun.'::text,''::text,'bir'::text,'bir'::text,'Yalan yok, şehrin en iyi puanlarını sen yazıyorsun.'::text),
(311679,34631,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hazudok, te írod ... legjobb értékeléseket a városban.'::text,'a'::text,'egy'::text,'egy'::text,'Nem hazudok, te írod a legjobb értékeléseket a városban.'::text),
(311691,34633,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr ehrliche Bewertung, klar. Vielleicht ... sie das Essen zuerst probieren.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Sehr ehrliche Bewertung, klar. Vielleicht sollte sie das Essen zuerst probieren.'::text),
(311695,34633,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже чесна оцінка, звісно. Може, вона ... спершу скуштувати їжу.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Дуже чесна оцінка, звісно. Може, вона мала б спершу скуштувати їжу.'::text),
(311694,34633,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una valoración muy honesta, claro. Quizá ... probar la comida primero.'::text,'debería'::text,'debería'::text,'debería'::text,'Una valoración muy honesta, claro. Quizá debería probar la comida primero.'::text),
(311693,34633,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Note très honnête, évidemment. Peut-être qu''elle ... goûter la nourriture d''abord.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Note très honnête, évidemment. Peut-être qu''elle devrait goûter la nourriture d''abord.'::text),
(311696,34633,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok dürüst bir puan, belli. Belki önce yemeği ...'::text,'tatmalı'::text,'tatmalı'::text,'tatmalı'::text,'Çok dürüst bir puan, belli. Belki önce yemeği tatmalı.'::text),
